  (void)conn;
  pthread_mutex_lock(&g_lock);
  status_conn = g_status_notify_conn;
  event_conn = g_agent_event_notify_conn;
  result_conn = g_agent_result_notify_conn;
  g_status_notify_conn = NULL;
  g_agent_event_notify_conn = NULL;
