  ret = k_work_schedule(&g_adv_restart_work, K_SECONDS(1));
  if (ret < 0)
    {
      syslog(LOG_WARNING,
             "[BLE] disconnected reason=0x%02x; restart schedule failed: %d\n",
             reason, ret);
    }
}

