   173	  bool join_thread = false;
   174	
   175	  pthread_mutex_lock(&display->lock);
   176	  if (display->audio_thread_started)
   177	    {
   178	      thread = display->audio_thread;
   179	      display->audio_thread_started = false;
   180	      join_thread = true;
   181	    }
   182	  pthread_mutex_unlock(&display->lock);
   183	
   184	  if (join_thread)
   185	    {
   186	      pthread_join(thread, NULL);
   187	    }
   188	}
