   612	static void display_render_app(velawear_display_t *display,
   613	                               const velawear_state_t *state)
   614	{
   615	  char content[384];
   616	  uint32_t elapsed;
   617	  uint32_t minutes;
   618	  uint32_t seconds;
   619	  uint32_t tenths;
   620	
   621	  if (display == NULL || state == NULL || !display->detail_active ||
   622	      display->metrics_label == NULL)
   623	    {
   624	      return;
   625	    }
   626	
   627	  content[0] = '\0';
   628	  switch ((velawear_display_app_t)display->active_app)
   629	    {
   630	      case VELAWEAR_APP_AUDIO:
   631	        snprintf(content, sizeof(content),
   632	                 "喇叭\n等待测试\n\n麦克风\n点击检查设备");
   633	        break;
   634	
   635	      case VELAWEAR_APP_MUSIC:
   636	        snprintf(content, sizeof(content),
   637	                 "内置旋律\n\n准备播放\n音量 70%%");
   638	        break;
   639	
   640	      case VELAWEAR_APP_MOTION:
   641	        snprintf(content, sizeof(content),
   642	                 "运动  %s\n跑步  %s\n今日活动 %lu\n运行时间 %lu 秒",
   643	                 state->is_moving ? "活动" : "静止",
   644	                 state->is_running ? "是" : "否",
   645	                 (unsigned long)state->move_count_today,
   646	                 (unsigned long)state->uptime_seconds);
   647	        break;
   648	
   649	      case VELAWEAR_APP_STOPWATCH:
   650	        elapsed = display->stopwatch_elapsed_ms;
   651	        if (display->stopwatch_running)
   652	          {
   653	            elapsed += display_now_ms() - display->stopwatch_started_ms;
   654	          }
   655	        minutes = elapsed / 60000;
   656	        seconds = (elapsed / 1000) % 60;
   657	        tenths = (elapsed / 100) % 10;
   658	        snprintf(content, sizeof(content), "%02lu:%02lu.%lu\n\n%s",
   659	                 (unsigned long)minutes, (unsigned long)seconds,
   660	                 (unsigned long)tenths,
   661	                 display->stopwatch_running ? "运行中" : "已暂停");
   662	        break;
   663	
   664	      case VELAWEAR_APP_TASKS:
   665	        snprintf(content, sizeof(content),
   666	                 "[完成] 音频初始化\n[完成] 喇叭测试\n[ ] 麦克风测试\n[ ] 音乐播放\n[ ] 功耗优化");
   667	        break;
   668	
   669	      case VELAWEAR_APP_DIAGNOSTICS:
   670	        snprintf(content, sizeof(content),
   671	                 "运行时间  %lu 秒\n剩余内存  %lu B\n电源模式  %d\n触摸      正常\n音频      点击测试",
   672	                 (unsigned long)state->uptime_seconds,
   673	                 (unsigned long)state->free_memory, state->power_mode);
   674	        break;
   675	
