 933	void display_manager_tick(velawear_display_t *display)
 934	{
 935	  uint32_t now;
 936	  velawear_state_t state;
 937	  lv_obj_t *alert_label;
 938	
 939	  if (display == NULL || !display->initialized)
 940	    {
 941	      return;
 942	    }
 943	
 944	  now = display_now_ms();
 945	  display_audio_poll(display);
 946	  pthread_mutex_lock(&display->lock);
 947	  if (display->alert_pending)
 948	    {
 949	      lv_obj_set_style_bg_color(lv_screen_active(), lv_color_hex(0x5b1111), 0);
 950	      lv_label_set_text(display->status_label, "主动提醒");
 951	      lv_obj_set_style_text_color(display->status_label,
 952	                                  lv_color_hex(0xfca5a5), 0);
 953	      alert_label = display->detail_active ? display->metrics_label :
 954	                    display->page_content[0];
 955	      if (alert_label != NULL)
 956	        {
 957	          lv_label_set_text(alert_label, display->pending_alert);
 958	          lv_obj_set_style_text_color(alert_label,
 959	                                      lv_color_hex(UI_TEXT_COLOR), 0);
 960	        }
 961	      if (g_alert_message != NULL && g_alert_overlay != NULL)
 962	        {
 963	          lv_label_set_text(g_alert_message, display->pending_alert);
 964	          lv_obj_clear_flag(g_alert_overlay, LV_OBJ_FLAG_HIDDEN);
 965	          lv_obj_move_foreground(g_alert_overlay);
 966	        }
 967	      display->alert_until_ms = now + 60000;
 968	      display->alert_active = true;
 969	      syslog(LOG_INFO,
 970	             "[Display] Alert consumed page=%u detail=%d label=%p hold=60000ms text=%s\n",
 971	             (unsigned int)display->page_index, display->detail_active ? 1 : 0,
 972	             alert_label, display->pending_alert);
 973	      display->alert_pending = false;
 974	    }
 975	  pthread_mutex_unlock(&display->lock);
 976	
 977	  if (display->alert_active)
 978	    {
 979	      if (now < display->alert_until_ms)
 980	        {
 981	          lv_timer_handler();
 982	          return;
 983	        }
 984	
 985	      display->alert_active = false;
 986	      syslog(LOG_INFO, "[Display] Alert expired\n");
 987	      if (g_alert_overlay != NULL)
 988	        {
 989	          lv_obj_add_flag(g_alert_overlay, LV_OBJ_FLAG_HIDDEN);
 990	        }
 991	      display_restore_theme(display);
 992	      display->last_update_ms = 0;
 993	    }
 994	
 995	  if (display->last_update_ms == 0 || now - display->last_update_ms >=
 996	      (display->active_app == VELAWEAR_APP_STOPWATCH &&
 997	       display->stopwatch_running ? 100 : 250))
 998	    {
 999	      state = state_manager_get_state(display->state_mgr);
1000	      if (display->detail_active)
1001	        {
1002	          display_render_app(display, &state);
1003	        }
1004	      else
1005	        {
1006	          display_render_top(display, &state);
1007	        }
1008	      display->last_update_ms = now;
1009	    }
1010	
1011	  lv_timer_handler();
1012	}
