   262	void audio_sensor_cleanup(velawear_audio_t *audio)
   263	{
   264	  if (audio == NULL)
   265	    {
   266	      return;
   267	    }
   268	
   269	  audio->stream_running = false;
   270	  if (audio->thread_started)
   271	    {
   272	      pthread_join(audio->thread, NULL);
