784	static void sf32lb52_bt_close(struct bt_driver_s *drv)
785	{
786	  int ret;
787	
788	  (void)drv;
789	
790	  g_sf32lb52_bt_priv.rxlen = 0;
791	
792	  /* Full deinit (not just disable) so that the next open re-initialises
793	   * the IPC queue from a clean state.  Without deinit, controller_init
794	   * is skipped on re-open (status != IDLE), and LCPU's ring-buffer
795	   * read pointer (reset on power-on) diverges from HCPU's stale write
796	   * pointer, causing all HCI commands to be silently dropped. */
797	  ret = sf32lb52_bt_controller_deinit();
798	  if (ret < 0)
799	    {
800	      wlerr("Failed to deinit HCI controller: %d\n", ret);
801	    }
802	}
