276	static int sf32lb52_bt_forward_packet(struct sf32lb52_bt_priv_s *priv,
277	                                      uint8_t *data, size_t len)
278	{
279	  enum bt_buf_type_e type;
280	  int ret;
281	
282	  if (len <= H4_HEADER_SIZE)
283	    {
284	      return -EINVAL;
285	    }
286	
287	  switch (data[0])
288	    {
289	      case H4_EVT:
290	        sf32lb52_bt_normalize_event(data, len);
291	#if SF32LB52_BT_ERROR_TRACE
292	        if (len >= 4 && data[1] == 0x10)
293	          {
294	            syslog(LOG_WARNING,
295	                   "sf32lb52 bth4 hardware error: status=%02x\n",
296	                   data[3]);
297	          }
298	#endif
299	#if SF32LB52_BT_CONN_TRACE
300	        if (len >= 7 && data[1] == BT_HCI_EVT_LE_META_EVENT &&
301	            data[3] == BT_HCI_EVT_LE_CONN_COMPLETE)
302	          {
303	            syslog(LOG_WARNING,
304	                   "sf32lb52 bth4 le conn complete: status=%02x handle=%02x%02x\n",
305	                   data[4], data[5], data[6]);
306	          }
307	        else if (len >= 7 && data[1] == BT_HCI_EVT_DISCONN_COMPLETE)
308	          {
309	            syslog(LOG_WARNING,
310	                   "sf32lb52 bth4 disconn complete: status=%02x handle=%02x%02x reason=%02x\n",
311	                   data[3], data[4], data[5], data[6]);
312	          }
313	#endif
314	#if SF32LB52_BT_CONN_TRACE
315	        if (len <= 8 && data[1] != BT_HCI_EVT_CMD_COMPLETE &&
316	            data[1] != BT_HCI_EVT_CMD_STATUS)
317	          {
318	            syslog(LOG_WARNING,
319	                   "sf32lb52 bth4 short event: code=%02x len=%u data=%02x%02x%02x%02x\n",
320	                   data[1], data[2],
321	                   len > 3 ? data[3] : 0, len > 4 ? data[4] : 0,
322	                   len > 5 ? data[5] : 0, len > 6 ? data[6] : 0);
323	          }
324	#endif
325	        if (len >= H4_HEADER_SIZE + sizeof(struct bt_hci_evt_hdr_s) + 4 &&
326	            data[2] >= 4 &&
327	            ((data[1] == BT_HCI_EVT_CMD_COMPLETE &&
328	              sf32lb52_bt_get_le16(&data[4]) == BT_HCI_OP_RESET) ||
329	             (data[1] == BT_HCI_EVT_CMD_STATUS &&
330	              sf32lb52_bt_get_le16(&data[5]) == BT_HCI_OP_RESET)))
331	          {
332	            (void)usleep(SF32LB52_BT_RESET_SETTLE_US);
333	          }
334	        type = BT_EVT;
335	        break;
336	
337	      case H4_ACL:
338	#if SF32LB52_BT_CONN_TRACE
339	        if (len >= 5)
340	          {
341	            syslog(LOG_WARNING,
342	                   "sf32lb52 bth4 rx acl: total=%lu handle=%02x%02x len=%02x%02x data=%02x%02x%02x%02x%02x%02x%02x\n",
343	                   (unsigned long)len, data[1], data[2], data[3], data[4],
344	                   len > 5 ? data[5] : 0, len > 6 ? data[6] : 0,
345	                   len > 7 ? data[7] : 0, len > 8 ? data[8] : 0,
346	                   len > 9 ? data[9] : 0, len > 10 ? data[10] : 0,
347	                   len > 11 ? data[11] : 0);
348	          }
349	#endif
350	        type = BT_ACL_IN;
351	        break;
352	
353	      case H4_ISO:
354	        type = BT_ISO_IN;
355	        break;
356	
357	      default:
358	        return -EINVAL;
359	    }
360	
361	  ret = bt_netdev_receive(&priv->drv,
362	                          type,
363	                          (void *)&data[H4_HEADER_SIZE],
364	                          len - H4_HEADER_SIZE);
365	  if (ret < 0)
366	    {
367	      wlerr("Failed to receive HCI packet: %d\n", ret);
368	    }
369	
370	  return ret;
371	}
