538	static int sf32lb52_bt_recv_cb(uint8_t *data, uint16_t len)
539	{
540	  struct sf32lb52_bt_priv_s *priv = &g_sf32lb52_bt_priv;
541	  ssize_t packet_len;
542	  int ret;
543	
544	  if (data == NULL || len == 0)
545	    {
546	      return -EINVAL;
547	    }
548	
549	
550	  if (priv->drop_rx_until_tx)
551	    {
552	      return OK;
553	    }
554	
555	  if (priv->rxlen + len > sizeof(priv->rxbuf))
556	    {
557	      syslog(LOG_ERR,
558	             "sf32lb52 bth4 rx overflow: pending=%lu incoming=%u\n",
559	             (unsigned long)priv->rxlen,
560	             len);
561	      priv->rxlen = 0;
562	    }
563	
564	  memcpy(&priv->rxbuf[priv->rxlen], data, len);
565	  priv->rxlen += len;
566	
567	#if SF32LB52_BT_TRACE
568	  syslog(LOG_INFO,
569	         "sf32lb52 bth4 recv: len=%u pending=%lu first=%02x\n",
570	         len, (unsigned long)priv->rxlen, priv->rxbuf[0]);
571	#endif
572	
573	  ret = OK;
574	
575	  while (priv->rxlen > 0)
576	    {
577	      packet_len = sf32lb52_bt_h4_packet_len(priv->rxbuf, priv->rxlen);
578	      if (packet_len == 0)
579	        {
580	          break;
581	        }
582	
583	      if (packet_len < 0)
584	        {
585	          syslog(LOG_WARNING,
586	                 "sf32lb52 bth4 drop invalid h4 type=%02x pending=%lu\n",
587	                 priv->rxbuf[0],
588	                 (unsigned long)priv->rxlen);
589	          memmove(priv->rxbuf, &priv->rxbuf[1], priv->rxlen - 1);
590	          priv->rxlen--;
591	          ret = -EINVAL;
592	          continue;
593	        }
594	
595	      if ((size_t)packet_len > priv->rxlen)
596	        {
597	          break;
598	        }
599	
600	#if SF32LB52_BT_TRACE
601	      if (priv->rxbuf[0] == H4_EVT && packet_len >= 3)
602	        {
603	          syslog(LOG_INFO,
604	                 "sf32lb52 bth4 event: code=%02x len=%u\\n",
605	                 priv->rxbuf[1], priv->rxbuf[2]);
606	        }
607	#endif
608	
609	      ret = sf32lb52_bt_forward_packet(priv, priv->rxbuf,
610	                   (size_t)packet_len);
611	
612	      priv->rxlen -= (size_t)packet_len;
613	      if (priv->rxlen > 0)
614	        {
615	          memmove(priv->rxbuf,
616	                  &priv->rxbuf[packet_len],
617	                  priv->rxlen);
618	        }
619	    }
620	
621	  return ret;
622	}
