   109	  pthread_mutex_unlock(&g_lock);
   110	
   111	  return bt_gatt_attr_read(conn, attr, buf, len, offset,
   112	                           &seconds, sizeof(seconds));
   113	}
   114	
   115	static ssize_t velawear_ble_write_threshold(struct bt_conn *conn,
   116	                                            const struct bt_gatt_attr *attr,
   117	                                            const void *buf, uint16_t len,
   118	                                            uint16_t offset, uint8_t flags)
   119	{
   120	  const uint8_t *data = (const uint8_t *)buf;
   121	  uint16_t seconds;
   122	
   123	  (void)conn;
   124	  (void)attr;
   125	  if (buf == NULL || offset != 0 || len != sizeof(uint16_t) ||
   126	      (flags & BT_GATT_WRITE_FLAG_PREPARE) != 0)
   127	    {
   128	      return -EINVAL;
   129	    }
   130	
   131	  seconds = (uint16_t)data[0] | ((uint16_t)data[1] << 8);
   132	  if (seconds < 10 || seconds > 3600)
   133	    {
   134	      return -EINVAL;
   135	    }
   136	
   137	  if (velawear_ble_set_sedentary_threshold(seconds) < 0)
   138	    {
   139	      return -EINVAL;
   140	    }
   141	
   142	  return len;
   143	}
   144	
   145	int velawear_ble_set_sedentary_threshold(uint16_t seconds)
   146	{
   147	  if (seconds < 10 || seconds > 3600)
   148	    {
   149	      return VELAWEAR_ERR_INVAL;
   150	    }
   151	
   152	  pthread_mutex_lock(&g_lock);
   153	  if (!g_initialized || g_config == NULL)
   154	    {
   155	      pthread_mutex_unlock(&g_lock);
   156	      return VELAWEAR_ERR_IO;
   157	    }
   158	
   159	  g_config->sedentary_threshold_sec = seconds;
   160	  pthread_mutex_unlock(&g_lock);
   161	  syslog(LOG_INFO, "[BLE] Sedentary threshold updated: %u s\n",
   162	         (unsigned int)seconds);
   163	  return VELAWEAR_OK;
   164	}
