   181	
   182	  pthread_mutex_lock(&g_lock);
   183	  old_conn = *notify_conn;
   184	  *notify_conn = enabled && conn != NULL ? bt_conn_ref(conn) : NULL;
   185	  *notify_enabled = enabled;
   186	  pthread_mutex_unlock(&g_lock);
   187	
   188	  if (old_conn != NULL)
   189	    {
   190	      bt_conn_unref(old_conn);
   191	    }
   192	
   193	  return sizeof(value);
   194	}
