   327	  value[2] = g_alert_active ? 1 : 0;
   328	  conn = g_status_notify_conn != NULL ? bt_conn_ref(g_status_notify_conn) : NULL;
   329	  pthread_mutex_unlock(&g_lock);
   330	
   331	  if (conn == NULL)
   332	    {
   333	      return;
   334	    }
   335	
   336	  (void)bt_gatt_notify(conn, &attr_velawear_svc[VELAWEAR_BLE_STATUS_ATTR_INDEX],
   337	                       value, sizeof(value));
   338	  bt_conn_unref(conn);
   339	}
