   341	static int velawear_ble_notify_agent_packet(uint16_t attr_index,
   342	                                            const uint8_t *frame,
   343	                                            uint16_t frame_size)
   344	{
   345	  bool notify_enabled;
   346	  struct bt_conn *notify_conn;
   347	  struct bt_conn *conn;
   348	  int ret;
   349	
   350	  pthread_mutex_lock(&g_lock);
   351	  if (attr_index == VELAWEAR_BLE_AGENT_EVENT_ATTR_INDEX)
   352	    {
   353	      notify_enabled = g_agent_event_notify_enabled;
   354	      notify_conn = g_agent_event_notify_conn;
   355	    }
   356	  else if (attr_index == VELAWEAR_BLE_AGENT_RESULT_ATTR_INDEX)
   357	    {
   358	      notify_enabled = g_agent_result_notify_enabled;
   359	      notify_conn = g_agent_result_notify_conn;
   360	    }
   361	  else
   362	    {
   363	      pthread_mutex_unlock(&g_lock);
   364	      return VELAWEAR_ERR_INVAL;
   365	    }
   366	
   367	  conn = notify_enabled && notify_conn != NULL ? bt_conn_ref(notify_conn) : NULL;
   368	  pthread_mutex_unlock(&g_lock);
   369	  if (conn == NULL)
   370	    {
   371	      return VELAWEAR_OK;
   372	    }
   373	
   374	  ret = bt_gatt_notify(conn, &attr_velawear_svc[attr_index], frame, frame_size);
   375	  bt_conn_unref(conn);
   376	  if (ret < 0)
   377	    {
   378	      syslog(LOG_WARNING, "[BLE] Agent notification failed: %d\n", ret);
   379	      return ret;
   380	    }
   381	
   382	  return VELAWEAR_OK;
   383	}
