   385	static uint8_t velawear_ble_percent_from_intensity(float intensity)
   386	{
   387	  if (intensity <= 0.0f)
   388	    {
   389	      return 0;
   390	    }
   391	
   392	  if (intensity >= 1.0f)
   393	    {
   394	      return 100;
   395	    }
   396	
   397	  return (uint8_t)(intensity * 100.0f);
   398	}
