   403	}
   404	
   405	int velawear_ble_publish_agent_event(const velawear_event_t *event)
   406	{
   407	  velawear_agent_event_t agent_event;
   408	  uint8_t frame[VELAWEAR_AGENT_EVENT_FRAME_SIZE];
   409	  int ret;
   410	
   411	  if (event == NULL || !g_initialized)
   412	    {
   413	      return VELAWEAR_ERR_INVAL;
   414	    }
   415	
   416	  memset(&agent_event, 0, sizeof(agent_event));
   417	  switch (event->type)
   418	    {
   419	      case VELAWEAR_EVENT_MOTION:
   420	        agent_event.event_type = VELAWEAR_AGENT_EVENT_MOTION;
   421	        agent_event.intensity_percent =
   422	            velawear_ble_percent_from_intensity(event->data.motion.intensity);
   423	        break;
   424	
   425	      case VELAWEAR_EVENT_FALL:
   426	        agent_event.event_type = VELAWEAR_AGENT_EVENT_FALL;
   427	        agent_event.priority = VELAWEAR_AGENT_PRIORITY_CRITICAL;
   428	        agent_event.intensity_percent = 100;
   429	        break;
   430	
   431	      case VELAWEAR_EVENT_AUDIO:
   432	        agent_event.event_type = VELAWEAR_AGENT_EVENT_AUDIO;
   433	        agent_event.intensity_percent = event->data.audio.active ? 100 : 0;
   434	        agent_event.value = velawear_ble_u16_saturate(event->data.audio.avg_abs);
   435	        agent_event.peak = velawear_ble_u16_saturate(event->data.audio.peak_abs);
   436	        if (event->data.audio.active)
   437	          {
   438	            agent_event.flags |= VELAWEAR_AGENT_EVENT_FLAG_ACTIVE;
   439	          }
   440	        break;
   441	
   442	      case VELAWEAR_EVENT_TIMER:
   443	        agent_event.event_type = VELAWEAR_AGENT_EVENT_SEDENTARY;
   444	        break;
   445	
   446	      default:
   447	        return VELAWEAR_ERR_NOSUPPORT;
   448	    }
   449	
   450	  pthread_mutex_lock(&g_lock);
   451	  agent_event.sequence = g_agent_event_sequence++;
   452	  if (g_alert_active)
   453	    {
   454	      agent_event.flags |= VELAWEAR_AGENT_EVENT_FLAG_ALERT;
   455	    }
   456	
   457	  ret = velawear_agent_encode_event(&agent_event, frame, sizeof(frame));
   458	  pthread_mutex_unlock(&g_lock);
   459	  if (ret < 0)
   460	    {
   461	      return ret;
   462	    }
   463	
   464	  return velawear_ble_notify_agent_packet(VELAWEAR_BLE_AGENT_EVENT_ATTR_INDEX,
   465	                                          frame, (uint16_t)ret);
   466	}
