 547	static void velawear_ble_disconnected(struct bt_conn *conn, uint8_t reason)
 548	{
 549	  struct bt_conn *status_conn;
 550	  struct bt_conn *event_conn;
 551	  struct bt_conn *result_conn;
 552	  int ret;
 553	
 554	  (void)conn;
 555	  pthread_mutex_lock(&g_lock);
 556	  status_conn = g_status_notify_conn;
 557	  event_conn = g_agent_event_notify_conn;
 558	  result_conn = g_agent_result_notify_conn;
 559	  g_status_notify_conn = NULL;
 560	  g_agent_event_notify_conn = NULL;
 561	  g_agent_result_notify_conn = NULL;
 562	  g_status_notify_enabled = false;
 563	  g_agent_event_notify_enabled = false;
 564	  g_agent_result_notify_enabled = false;
 565	  pthread_mutex_unlock(&g_lock);
 566	
 567	  if (status_conn != NULL)
 568	    {
 569	      bt_conn_unref(status_conn);
 570	    }
 571	
 572	  if (event_conn != NULL)
 573	    {
 574	      bt_conn_unref(event_conn);
 575	    }
 576	
 577	  if (result_conn != NULL)
 578	    {
 579	      bt_conn_unref(result_conn);
