 594	static void *velawear_imu_thread(void *context)
 595	{
 596	  velawear_agent_t *agent = (velawear_agent_t *)context;
 597	  bool fall_reported = false;
 598	  int last_motion_type = -1;
 599	
 600	  while (agent->running)
 601	    {
 602	      imu_data_t sample;
 603	      motion_state_t motion;
 604	      velawear_event_t event;
 605	      int period_us = 20000;
 606	
 607	      if (imu_sensor_read(&agent->imu, &sample) == VELAWEAR_OK)
 608	        {
 609	          int motion_type;
 610	
 611	          motion = imu_sensor_get_motion_state(&agent->imu);
 612	          motion_type = motion.is_running ? 2 :
 613	                        (motion.is_moving ? 1 : 0);
 614	
 615	          memset(&event, 0, sizeof(event));
 616	          event.type = VELAWEAR_EVENT_MOTION;
 617	          event.priority = VELAWEAR_PRIORITY_NORMAL;
 618	          event.timestamp = sample.timestamp;
 619	          event.data.motion.motion_type = motion_type;
 620	          event.data.motion.intensity = motion.motion_intensity;
 621	
 622	          if (motion_type != last_motion_type)
 623	            {
 624	              const char *motion_name = motion_type == 2 ? "跑步" :
 625	                                        (motion_type == 1 ? "活动" : "静止");
 626	              syslog(LOG_INFO, "[MVP] IMU state=%s intensity=%.2f\n",
 627	                     motion_name, motion.motion_intensity);
 628	              velawear_ble_update_motion(motion_type,
 629	                                         motion.motion_intensity);
 630	              /* 活动恢复时清除 BLE 告警状态。 */
 631	              if (last_motion_type == 0 && motion_type != 0)
 632	                {
 633	                  velawear_ble_set_alert(false);
 634	                }
 635	              last_motion_type = motion_type;
 636	
 637	              /* Motion state is edge-triggered for the event queue.  The IMU
 638	               * still samples at its configured rate for fall detection, but
 639	               * repeated identical states must not consume all MQ objects. */
 640	              if (event_manager_push(&agent->events, &event) < 0)
 641	                {
 642	                  syslog(LOG_WARNING,
 643	                         "[VelaWear] Failed to queue motion event\n");
 644	                }
 645	            }
 646	
 647	          if (motion.fall_detected && !fall_reported)
 648	            {
 649	              event.type = VELAWEAR_EVENT_FALL;
 650	              event.priority = VELAWEAR_PRIORITY_CRITICAL;
 651	              if (event_manager_push(&agent->events, &event) < 0)
 652	                {
 653	                  syslog(LOG_WARNING,
 654	                         "[VelaWear] Failed to queue fall event\n");
 655	                }
 656	              fall_reported = true;
 657	            }
 658	          else if (!motion.fall_detected)
 659	            {
 660	              fall_reported = false;
 661	            }
 662	        }
 663	
 664	      if (agent->config.imu_sample_rate_hz > 0)
 665	        {
 666	          period_us = 1000000 / agent->config.imu_sample_rate_hz;
 667	          if (period_us < 1000)
 668	            {
 669	              period_us = 1000;
 670	            }
 671	        }
 672	
 673	      usleep(period_us);
 674	    }
 675	
 676	  return NULL;
 677	}
