 679	static int velawear_init(velawear_agent_t *agent)
 680	{
 681	  int ret;
 682	
 683	  /* Initialize configuration */
 684	
 685	  ret = velawear_config_init(&agent->config);
 686	  if (ret < 0)
 687	    {
 688	      syslog(LOG_ERR, "[VelaWear] Config init failed: %d\n", ret);
 689	      return ret;
 690	    }
 691	
 692	  /* Initialize event manager */
 693	
 694	  ret = event_manager_init(&agent->events);
 695	  if (ret < 0)
 696	    {
 697	      syslog(LOG_ERR, "[VelaWear] Event manager init failed: %d\n", ret);
 698	      return ret;
 699	    }
 700	
 701	  /* Initialize state manager */
 702	
 703	  ret = state_manager_init(&agent->state_mgr);
 704	  if (ret < 0)
 705	    {
 706	      syslog(LOG_ERR, "[VelaWear] State manager init failed: %d\n", ret);
 707	      return ret;
 708	    }
 709	  agent->state = state_manager_get_state(&agent->state_mgr);
 710	
 711	  /* Initialize the LCD/LVGL status page on the main thread.  LVGL keeps
 712	   * context in task-local storage, so timer handling stays in this thread. */
 713	#ifndef VELAWEAR_ENABLE_DISPLAY
 714	#define VELAWEAR_ENABLE_DISPLAY 1
 715	#endif
 716	#if VELAWEAR_ENABLE_DISPLAY
 717	  ret = display_manager_init(&agent->display, &agent->state_mgr,
 718	                             &agent->events);
 719	  if (ret < 0)
 720	    {
 721	      syslog(LOG_WARNING, "[VelaWear] Display init failed: %d\n", ret);
 722	      /* Non-fatal: the agent remains usable without a display. */
 723	    }
 724	#else
 725	  ret = -ENOTSUP;
 726	  syslog(LOG_INFO, "[Display] disabled for BLE isolation\n");
 727	#endif
 728	
 729	  /*
 730	   * Core MVP mode keeps BLE optional so a controller/HCI fault cannot block
 731	   * the IMU -> Agent -> LCD reminder loop. Re-enable with
 732	   * -DVELAWEAR_ENABLE_BLE=1 after the HCI path is verified.
 733	   */
 734	#ifndef VELAWEAR_ENABLE_BLE
 735	#define VELAWEAR_ENABLE_BLE 0
 736	#endif
 737	#if VELAWEAR_ENABLE_BLE
 738	  ret = velawear_ble_init(&agent->config, &agent->events);
 739	  if (ret < 0)
 740	    {
 741	      syslog(LOG_WARNING, "[VelaWear] BLE init failed: %d\n", ret);
 742	    }
 743	  else
 744	    {
 745	      agent->ble_available = true;
 746	    }
 747	  syslog(LOG_INFO, "[BLE] init result=%d available=%d\n", ret,
 748	         agent->ble_available ? 1 : 0);
 749	#else
 750	  ret = -ENOTSUP;
 751	  syslog(LOG_INFO, "[BLE] deferred; core MVP mode\n");
 752	#endif
 753	
 754	  velawear_buttons_open();
 755	
 756	  /* Initialize decision engine */
 757	
 758	  ret = decision_engine_init(&agent->engine, &agent->config);
 759	  if (ret < 0)
 760	    {
 761	      syslog(LOG_ERR, "[VelaWear] Decision engine init failed: %d\n", ret);
 762	      return ret;
 763	    }
 764	
 765	  /* Initialize action manager */
 766	
 767	  ret = action_manager_init(&agent->actions);
 768	  if (ret < 0)
 769	    {
 770	      syslog(LOG_ERR, "[VelaWear] Action manager init failed: %d\n", ret);
 771	      return ret;
 772	    }
 773	
 774	  ret = decision_engine_set_action_manager(&agent->engine,
 775	                                             &agent->actions);
 776	  if (ret < 0)
 777	    {
 778	      syslog(LOG_ERR, "[VelaWear] Decision action routing setup failed: %d\n",
 779	             ret);
 780	      return ret;
1010	
1011	  /* The action manager worker performs callbacks; wake it after evaluation. */
1012	  return action_manager_process(&agent->actions);
1013	}
