1015	static void velawear_publish_agent_event(velawear_agent_t *agent,
1016	                                         const velawear_event_t *event)
1017	{
1018	  static int last_motion_type = -1;
1019	  int ret;
1020	
1021	  if (agent == NULL || event == NULL || !agent->ble_available)
1022	    {
1023	      return;
1024	    }
1025	
1026	  if (event->type == VELAWEAR_EVENT_MOTION)
1027	    {
1028	      if (event->data.motion.motion_type == last_motion_type)
1029	        {
1030	          return;
1031	        }
1032	
1033	      last_motion_type = event->data.motion.motion_type;
1034	    }
1035	  else if (event->type != VELAWEAR_EVENT_FALL &&
1036	           event->type != VELAWEAR_EVENT_AUDIO &&
1037	           event->type != VELAWEAR_EVENT_TIMER)
1038	    {
1039	      return;
1040	    }
1041	
1042	  ret = velawear_ble_publish_agent_event(event);
1043	  if (ret < 0)
1044	    {
1045	      syslog(LOG_WARNING, "[BLE] Agent event publish failed: %d\n", ret);
1046	    }
1047	}
