1049	static int velawear_handle_agent_command(velawear_agent_t *agent,
1050	                                         const velawear_event_t *event)
1051	{
1052	  velawear_agent_command_t command;
1053	  const char *message = NULL;
1054	  int result = VELAWEAR_AGENT_COMMAND_RESULT_REJECTED;
1055	  int ret;
1056	
1057	  if (agent == NULL || event == NULL || event->data.ble.length < 0 ||
1058	      velawear_agent_decode_command((const uint8_t *)event->data.ble.data,
1059	                                    (uint16_t)event->data.ble.length,
1060	                                    &command) < 0)
1061	    {
1062	      syslog(LOG_WARNING, "[BLE] Invalid queued Agent command\n");
1063	      return VELAWEAR_OK;
1064	    }
1065	
1066	  switch (command.command_id)
1067	    {
1068	      case VELAWEAR_AGENT_COMMAND_ACK_ALERT:
1069	        velawear_ble_set_alert(false);
1070	        result = VELAWEAR_AGENT_COMMAND_RESULT_OK;
1071	        break;
1072	
1073	      case VELAWEAR_AGENT_COMMAND_SET_SEDENTARY_THRESHOLD:
1074	        ret = velawear_ble_set_sedentary_threshold(command.argument);
1075	        result = ret == VELAWEAR_OK ? VELAWEAR_AGENT_COMMAND_RESULT_OK :
1076	                                      VELAWEAR_AGENT_COMMAND_RESULT_EXECUTION_FAILED;
1077	        break;
1078	
1079	      case VELAWEAR_AGENT_COMMAND_SHOW_REMINDER:
1080	        if (command.argument == VELAWEAR_AGENT_REMINDER_HYDRATE)
1081	          {
1082	            message = "AI 建议：补充水分";
1083	          }
1084	        else if (command.argument == VELAWEAR_AGENT_REMINDER_REST)
1085	          {
1086	            message = "AI 建议：休息一下";
1087	          }
1088	        else
1089	          {
1090	            message = "AI 建议：起来活动一下";
1091	          }
1092	
1093	        if (agent->display.initialized)
1094	          {
1095	            display_manager_show_alert(&agent->display, message);
1096	          }
