    20	int64_t sys_clock_tick_get(void)
    21	{
    22	#if defined(CONFIG_SYSTEM_TIME64)
    23		return clock_systime_ticks();
    24	#else
    25		static int64_t g_tick;
    26	
    27		unsigned int state = enter_critical_section();
    28	
    29		uint32_t tick = clock_systime_ticks();
    30	
    31		g_tick += (uint32_t)(tick - (uint32_t)g_tick);
    32	
    33		leave_critical_section(state);
    34	
    35		return g_tick;
    36	#endif
    37	}
    38	
    39	int64_t k_uptime_ticks(void)
    40	{
    41		return sys_clock_tick_get();
    42	}
    43	
    44	k_timeout_t sys_timepoint_timeout(k_timepoint_t timepoint)
    45	{
    46		uint64_t now, remaining;
    47	
    48		if (timepoint.tick == UINT64_MAX) {
    49			return K_FOREVER;
    50		}
    51		if (timepoint.tick == 0) {
    52			return K_NO_WAIT;
    53		}
    54	
    55		now = sys_clock_tick_get();
    56		remaining = (timepoint.tick > now) ? (timepoint.tick - now) : 0;
    57		return K_TICKS(remaining);
    58	}
    59	
    60	k_timepoint_t sys_timepoint_calc(k_timeout_t timeout)
    61	{
    62		k_timepoint_t timepoint;
    63	
    64		if (K_TIMEOUT_EQ(timeout, K_FOREVER)) {
    65			timepoint.tick = UINT64_MAX;
    66		} else if (K_TIMEOUT_EQ(timeout, K_NO_WAIT)) {
    67			timepoint.tick = 0;
    68		} else {
    69			k_ticks_t dt = timeout.ticks;
    70	
    71			if (IS_ENABLED(CONFIG_TIMEOUT_64BIT) && Z_TICK_ABS(dt) >= 0) {
    72				timepoint.tick = Z_TICK_ABS(dt);
    73			} else {
    74				timepoint.tick = sys_clock_tick_get() + MAX(1, dt);
    75			}
    76		}
    77	
    78		return timepoint;
    79	}
