   213	int event_manager_push(velawear_events_t *events, velawear_event_t *event)
   214	{
   215	  uintptr_t message;
   216	  int slot = -1;
   217	  int ret;
   218	
   219	  if (events == NULL || events->queue == (mqd_t)-1 || event == NULL)
   220	    {
   221	      return VELAWEAR_ERR_IO;
   222	    }
   223	
   224	  pthread_mutex_lock(&events->pool_lock);
   225	  /* Keep one pool slot for an Agent command.  Sensor producers must not
   226	   * prevent a connected BLE client from acknowledging or changing state. */
   227	  for (int i = 0; i < EVENT_POOL_SIZE - 1; i++)
   228	    {
   229	      if (!events->pool_used[i])
   230	        {
   231	          slot = i;
   232	          events->pool_used[i] = true;
   233	          memcpy(&events->pool[i], event, sizeof(*event));
   234	          break;
   235	        }
   236	    }
   237	
   238	  if (slot < 0 && event->type == VELAWEAR_EVENT_BLE_MSG &&
   239	      !events->pool_used[EVENT_POOL_SIZE - 1])
   240	    {
   241	      slot = EVENT_POOL_SIZE - 1;
   242	      events->pool_used[slot] = true;
   243	      memcpy(&events->pool[slot], event, sizeof(*event));
   244	    }
   245	  pthread_mutex_unlock(&events->pool_lock);
   246	
   247	  if (slot < 0)
   248	    {
   249	      return VELAWEAR_ERR_NOMEM;
   250	    }
   251	
   252	  /* The queue carries a stable pool slot, not a heap pointer. */
   253	  message = (uintptr_t)(slot + 1);
   254	  ret = mq_send(events->queue, (const char *)&message,
   255	                sizeof(message), event->priority);
   256	  if (ret < 0)
   257	    {
   258	      pthread_mutex_lock(&events->pool_lock);
   259	      events->pool_used[slot] = false;
   260	      pthread_mutex_unlock(&events->pool_lock);
   261	      syslog(LOG_WARNING, "[EventMgr] Failed to push event: %d\n", errno);
   262	      return VELAWEAR_ERR_IO;
   263	    }
   264	
   265	  return VELAWEAR_OK;
   266	}
   267	
   268	int event_manager_pop(velawear_events_t *events, velawear_event_t *event,
   269	                      int timeout_ms)
   270	{
   271	  struct timespec timeout;
   272	  uintptr_t message;
   273	  ssize_t nbytes;
   274	  int slot;
   275	
   276	  if (events == NULL || events->queue == (mqd_t)-1 || event == NULL)
   277	    {
   278	      return VELAWEAR_ERR_IO;
   279	    }
   280	
   281	  /* Calculate timeout */
   282	  clock_gettime(CLOCK_REALTIME, &timeout);
   283	  timeout.tv_sec += timeout_ms / 1000;
   284	  timeout.tv_nsec += (timeout_ms % 1000) * 1000000;
   285	  if (timeout.tv_nsec >= 1000000000)
   286	    {
   287	      timeout.tv_sec++;
   288	      timeout.tv_nsec -= 1000000000;
   289	    }
   290	
   291	  nbytes = mq_timedreceive(events->queue, (char *)&message,
   292	                           sizeof(message), NULL, &timeout);
   293	  if (nbytes < 0)
   294	    {
   295	      if (errno == ETIMEDOUT)
   296	        {
   297	          return VELAWEAR_ERR_TIMEOUT;
   298	        }
   299	
   300	      return VELAWEAR_ERR_IO;
   301	    }
   302	
   303	  if (nbytes != sizeof(message) || message == 0 ||
   304	      message > EVENT_POOL_SIZE)
   305	    {
   306	      return VELAWEAR_ERR_IO;
   307	    }
   308	
   309	  slot = (int)message - 1;
   310	  pthread_mutex_lock(&events->pool_lock);
   311	  if (!events->pool_used[slot])
   312	    {
   313	      pthread_mutex_unlock(&events->pool_lock);
   314	      return VELAWEAR_ERR_IO;
   315	    }
   316	
   317	  memcpy(event, &events->pool[slot], sizeof(*event));
   318	  events->pool_used[slot] = false;
   319	  pthread_mutex_unlock(&events->pool_lock);
   320	
   321	  return VELAWEAR_OK;
   322	}
   323	
   324	int event_manager_register_handler(velawear_events_t *events,
   325	                                   uint32_t event_type,
   326	                                   event_handler_t handler,
   327	                                   void *context,
   328	                                   int priority)
   329	{
   330	  pthread_mutex_lock(&events->lock);
   331	
   332	  if (events->handler_count >= EVENT_HANDLER_MAX)
   333	    {
   334	      pthread_mutex_unlock(&events->lock);
   335	      return VELAWEAR_ERR_NOMEM;
   336	    }
   337	
   338	  events->handlers[events->handler_count].event_type = event_type;
   339	  events->handlers[events->handler_count].handler = handler;
   340	  events->handlers[events->handler_count].context = context;
   341	  events->handlers[events->handler_count].priority = priority;
   342	  events->handler_count++;
   343	
   344	  pthread_mutex_unlock(&events->lock);
   345	
   346	  syslog(LOG_INFO, "[EventMgr] Registered handler for type %lu\n",
   347	         (unsigned long)event_type);
   348	  return VELAWEAR_OK;
   349	}

