   889	      syslog(LOG_ERR, "[VelaWear] Action manager start failed: %d\n", ret);
   890	      return ret;
   891	    }
   892	
   893	  /* Decision rules are evaluated synchronously for each event. */
   894	
   895	  /* Mark agent as running before starting the sensor producer. */
   896	
   897	  agent->running = true;
   898	  ret = velawear_watchdog_start(agent);
   899	  if (ret < 0)
