   922	          agent->running = false;
   923	          syslog(LOG_ERR, "[VelaWear] IMU thread start failed: %d\n", ret);
   924	          return VELAWEAR_ERR_IO;
   925	        }
   926	      agent->imu_thread_started = true;
   927	    }
   928	  return VELAWEAR_OK;
   929	}
