   931	static void velawear_cleanup(velawear_agent_t *agent)
   932	{
   933	  /* Stop subsystems in reverse order */
   934	
   935	  agent->running = false;
   936	  velawear_watchdog_stop(agent);
   937	  if (agent->imu_thread_started)
   938	    {
   939	      pthread_join(agent->imu_thread, NULL);
   940	      agent->imu_thread_started = false;
   941	    }
   942	
   943	  audio_sensor_cleanup(&agent->audio);
   944	  velawear_llm_cleanup(&agent->llm);
   945	  velawear_ble_cleanup();
   946	  imu_sensor_cleanup(&agent->imu);
   947	  action_manager_cleanup(&agent->actions);
   948	  event_manager_cleanup(&agent->events);
   949	  decision_engine_cleanup(&agent->engine);
   950	  velawear_buttons_close();
   951	  display_manager_cleanup(&agent->display);
   952	  state_manager_cleanup(&agent->state_mgr);
   953	  velawear_config_cleanup(&agent->config);
