   962	static int velawear_event_handler(velawear_event_t *event, void *context)
   963	{
   964	  velawear_agent_t *agent = (velawear_agent_t *)context;
   965	  velawear_state_t state;
   966	  velawear_action_t action;
   967	  int rule_id;
   968	  int ret;
   969	
   970	  if (event->type == VELAWEAR_EVENT_BLE_MSG)
   971	    {
   972	      return velawear_handle_agent_command(agent, event);
   973	    }
   974	
   975	  if (event->type == VELAWEAR_EVENT_AUDIO)
   976	    {
   977	      syslog(LOG_INFO,
   978	             "[Audio] event=%s avg_abs=%lu peak_abs=%lu active=%d\n",
   979	             event->data.audio.text,
   980	             (unsigned long)event->data.audio.avg_abs,
   981	             (unsigned long)event->data.audio.peak_abs,
   982	             event->data.audio.active ? 1 : 0);
   983	    }
   984	
   985	  ret = state_manager_update_from_event(&agent->state_mgr, event);
   986	  if (ret < 0)
   987	    {
   988	      return ret;
   989	    }
   990	
   991	  state = state_manager_get_state(&agent->state_mgr);
   992	  agent->state = state;
   993	  velawear_publish_agent_event(agent, event);
   994	  rule_id = decision_engine_evaluate(&agent->engine, &state, event);
   995	
   996	  /* Every matched rule produces a traceable action.  Rule-specific handlers
   997	   * can replace this log action later without changing the event pipeline. */
   998	  if (rule_id >= 0 && event->type != VELAWEAR_EVENT_MOTION &&
   999	      event->type != VELAWEAR_EVENT_FALL)
  1000	    {
  1001	      memset(&action, 0, sizeof(action));
  1002	      action.type = VELAWEAR_ACTION_LOG;
  1003	      action.priority = event->priority;
  1004	      ret = action_manager_execute(&agent->actions, &action);
  1005	      if (ret < 0)
  1006	        {
  1007	          return ret;
  1008	        }
  1009	    }
  1010	
  1011	  /* The action manager worker performs callbacks; wake it after evaluation. */
  1012	  return action_manager_process(&agent->actions);
  1013	}
