   145	int velawear_ble_set_sedentary_threshold(uint16_t seconds)
   146	{
   147	  if (seconds < 10 || seconds > 3600)
   148	    {
   149	      return VELAWEAR_ERR_INVAL;
   150	    }
   151	
   152	  pthread_mutex_lock(&g_lock);
   153	  if (!g_initialized || g_config == NULL)
   154	    {
   155	      pthread_mutex_unlock(&g_lock);
   156	      return VELAWEAR_ERR_IO;
   157	    }
   158	
   159	  g_config->sedentary_threshold_sec = seconds;
   160	  pthread_mutex_unlock(&g_lock);
   161	  syslog(LOG_INFO, "[BLE] Sedentary threshold updated: %u s\n",
   162	         (unsigned int)seconds);
   163	  return VELAWEAR_OK;
   164	}
