   230	static ssize_t velawear_ble_write_agent_command(
   231	    struct bt_conn *conn, const struct bt_gatt_attr *attr, const void *buf,
   232	    uint16_t len, uint16_t offset, uint8_t flags)
   233	{
   234	  const uint8_t *data = (const uint8_t *)buf;
   235	  velawear_agent_command_t command;
   236	  velawear_event_t event;
   237	  int ret;
   238	
   239	  (void)conn;
   240	  (void)attr;
   241	  if (buf == NULL || offset != 0 ||
   242	      (flags & BT_GATT_WRITE_FLAG_PREPARE) != 0 ||
   243	      velawear_agent_decode_command(data, len, &command) < 0)
   244	    {
   245	      return -EINVAL;
   246	    }
   247	
   248	  pthread_mutex_lock(&g_lock);
   249	  if (g_events == NULL ||
   250	      (g_have_last_agent_command_sequence &&
   251	       !velawear_agent_command_sequence_is_newer(
   252	           command.sequence, g_last_agent_command_sequence)))
   253	    {
   254	      pthread_mutex_unlock(&g_lock);
   255	      return -EALREADY;
   256	    }
   257	
   258	  g_last_agent_command_sequence = command.sequence;
   259	  g_have_last_agent_command_sequence = true;
   260	  pthread_mutex_unlock(&g_lock);
   261	
   262	  memset(&event, 0, sizeof(event));
   263	  event.type = VELAWEAR_EVENT_BLE_MSG;
   264	  event.priority = VELAWEAR_PRIORITY_HIGH;
   265	  event.data.ble.length = len;
   266	  memcpy(event.data.ble.data, data, len);
   267	  ret = event_manager_push(g_events, &event);
   268	  if (ret < 0)
   269	    {
   270	      syslog(LOG_WARNING, "[BLE] Agent command queue full: %d\n", ret);
   271	      return BT_GATT_ERR(BT_ATT_ERR_INSUFFICIENT_RESOURCES);
   272	    }
   273	
   274	  syslog(LOG_INFO, "[BLE] Agent command queued: seq=%u id=%u\n",
   275	         (unsigned int)command.sequence, (unsigned int)command.command_id);
   276	  return len;
   277	}
