   951	void display_manager_tick(velawear_display_t *display)
   952	{
   953	  uint32_t now;
   954	  velawear_state_t state;
   955	  lv_obj_t *alert_label;
   956	
   957	  if (display == NULL || !display->initialized)
   958	    {
   959	      return;
   960	    }
   961	
   962	  now = display_now_ms();
   963	  display_audio_poll(display);
   964	  pthread_mutex_lock(&display->lock);
   965	  if (display->alert_pending)
   966	    {
   967	      lv_obj_set_style_bg_color(lv_screen_active(), lv_color_hex(0x5b1111), 0);
   968	      lv_label_set_text(display->status_label, "主动提醒");
   969	      lv_obj_set_style_text_color(display->status_label,
   970	                                  lv_color_hex(0xfca5a5), 0);
   971	      alert_label = display->detail_active ? display->metrics_label :
   972	                    display->page_content[0];
   973	      if (alert_label != NULL)
   974	        {
   975	          lv_label_set_text(alert_label, display->pending_alert);
   976	          lv_obj_set_style_text_color(alert_label,
   977	                                      lv_color_hex(UI_TEXT_COLOR), 0);
   978	        }
   979	      if (g_alert_message != NULL && g_alert_overlay != NULL)
   980	        {
   981	          lv_label_set_text(g_alert_message, display->pending_alert);
   982	          lv_obj_clear_flag(g_alert_overlay, LV_OBJ_FLAG_HIDDEN);
   983	          lv_obj_move_foreground(g_alert_overlay);
   984	        }
   985	      display->alert_until_ms = now + 60000;
   986	      display->alert_active = true;
   987	      syslog(LOG_INFO,
   988	             "[Display] Alert consumed page=%u detail=%d label=%p hold=60000ms text=%s\n",
   989	             (unsigned int)display->page_index, display->detail_active ? 1 : 0,
   990	             alert_label, display->pending_alert);
   991	      display->alert_pending = false;
   992	    }
   993	  pthread_mutex_unlock(&display->lock);
   994	
   995	  if (display->alert_active)
   996	    {
   997	      if (now < display->alert_until_ms)
   998	        {
   999	          lv_timer_handler();
  1000	          return;
  1001	        }
  1002	
  1003	      display->alert_active = false;
  1004	      syslog(LOG_INFO, "[Display] Alert expired\n");
  1005	      if (g_alert_overlay != NULL)
  1006	        {
  1007	          lv_obj_add_flag(g_alert_overlay, LV_OBJ_FLAG_HIDDEN);
  1008	        }
  1009	      display_restore_theme(display);
  1010	      display->last_update_ms = 0;
  1011	    }
  1012	
  1013	  if (display->last_update_ms == 0 || now - display->last_update_ms >=
  1014	      (display->active_app == VELAWEAR_APP_STOPWATCH &&
  1015	       display->stopwatch_running ? 100 : 250))
  1016	    {
  1017	      state = state_manager_get_state(display->state_mgr);
  1018	      if (display->detail_active)
  1019	        {
  1020	          display_render_app(display, &state);
  1021	        }
  1022	      else
  1023	        {
  1024	          display_render_top(display, &state);
  1025	        }
  1026	      display->last_update_ms = now;
  1027	    }
  1028	
  1029	  lv_timer_handler();
  1030	}
