   604	    }
   605	
   606	  g_config = config;
   607	  g_events = events;
   608	  ret = pthread_mutex_init(&g_lock, NULL);
   609	  if (ret != 0)
   610	    {
   611	      g_config = NULL;
   612	      g_events = NULL;
   613	      return -ret;
   614	    }
   615	
   616	  g_alert_active = false;
   617	  g_status_notify_enabled = false;
   618	  g_status_notify_conn = NULL;
   619	  g_agent_event_notify_enabled = false;
