   639	    }
   640	
   641	  ret = bt_conn_cb_register(&velawear_conn_callbacks);
   642	  if (ret < 0)
   643	    {
   644	      pthread_mutex_destroy(&g_lock);
   645	      g_config = NULL;
   646	      g_events = NULL;
   647	      syslog(LOG_WARNING, "[BLE] Connection callback registration failed: %d\n",
   648	             ret);
