   656	    {
   657	      pthread_mutex_destroy(&g_lock);
   658	      g_config = NULL;
   659	      g_events = NULL;
   660	      syslog(LOG_WARNING, "[BLE] Advertising start failed: %d\n", ret);
   661	      return ret;
   662	    }
