     1	/* VelaWear Agent - compact BLE Agent protocol */
     2	
     3	#include <errno.h>
     4	#include <stdbool.h>
     5	#include <stdint.h>
     6	#include <stddef.h>
     7	
     8	#include "velawear_agent_protocol.h"
     9	
    10	static bool velawear_agent_command_is_known(uint8_t command_id)
    11	{
    12	  return command_id == VELAWEAR_AGENT_COMMAND_ACK_ALERT ||
    13	         command_id == VELAWEAR_AGENT_COMMAND_SET_SEDENTARY_THRESHOLD ||
    14	         command_id == VELAWEAR_AGENT_COMMAND_SHOW_REMINDER;
    15	}
    16	
    17	static bool velawear_agent_command_is_valid(uint8_t command_id,
    18	                                            uint16_t argument)
    19	{
    20	  if (!velawear_agent_command_is_known(command_id))
    21	    {
    22	      return false;
    23	    }
    24	
    25	  switch (command_id)
    26	    {
    27	      case VELAWEAR_AGENT_COMMAND_ACK_ALERT:
    28	        return argument == 0;
    29	
    30	      case VELAWEAR_AGENT_COMMAND_SET_SEDENTARY_THRESHOLD:
    31	        return argument >= 10 && argument <= 3600;
    32	
    33	      case VELAWEAR_AGENT_COMMAND_SHOW_REMINDER:
    34	        return argument <= VELAWEAR_AGENT_REMINDER_REST;
    35	
    36	      default:
    37	        return false;
    38	    }
    39	}
    40	
    41	int velawear_agent_encode_event(const velawear_agent_event_t *event,
    42	                                uint8_t *frame, uint16_t frame_size)
    43	{
    44	  if (event == NULL || frame == NULL ||
    45	      frame_size < VELAWEAR_AGENT_EVENT_FRAME_SIZE)
    46	    {
    47	      return -EINVAL;
    48	    }
    49	
    50	  frame[0] = VELAWEAR_AGENT_PROTOCOL_VERSION;
    51	  frame[1] = event->event_type;
    52	  frame[2] = (uint8_t)(event->sequence & 0xff);
    53	  frame[3] = (uint8_t)(event->sequence >> 8);
    54	  frame[4] = event->priority;
    55	  frame[5] = event->intensity_percent;
    56	  frame[6] = (uint8_t)(event->value & 0xff);
    57	  frame[7] = (uint8_t)(event->value >> 8);
    58	  frame[8] = (uint8_t)(event->peak & 0xff);
    59	  frame[9] = (uint8_t)(event->peak >> 8);
    60	  frame[10] = event->flags;
    61	  return VELAWEAR_AGENT_EVENT_FRAME_SIZE;
    62	}
    63	
    64	int velawear_agent_decode_command(const uint8_t *frame, uint16_t frame_size,
    65	                                  velawear_agent_command_t *command)
    66	{
    67	  uint8_t command_id;
    68	  uint16_t argument;
    69	
    70	  if (frame == NULL || command == NULL ||
    71	      frame_size != VELAWEAR_AGENT_COMMAND_FRAME_SIZE ||
    72	      frame[0] != VELAWEAR_AGENT_PROTOCOL_VERSION)
    73	    {
    74	      return -EINVAL;
    75	    }
    76	
    77	  command_id = frame[1];
    78	  argument = (uint16_t)frame[4] | ((uint16_t)frame[5] << 8);
    79	  if (!velawear_agent_command_is_valid(command_id, argument))
    80	    {
    81	      return -EINVAL;
    82	    }
    83	
    84	  command->sequence = (uint16_t)frame[2] | ((uint16_t)frame[3] << 8);
    85	  command->command_id = command_id;
    86	  command->argument = argument;
    87	  return 0;
    88	}
