section_re = re.compile(
    r"\\*\\*\\* Update File: ([^\\n]+)\\n(.*?)(?=\\n\\*\\*\\* (?:Update|Add|Delete) File:|\\n\\*\\*\\* End Patch)",
    re.S,
)

sections = list(section_re.finditer(patch))
if not sections:
    raise SystemExit("no update sections found")

for section in sections:
    rel = section.group(1).strip()
    path = root / rel
    if not path.is_file():
        raise SystemExit(f"target not found: {path}")

    original_text = path.read_text(encoding="utf-8")
    had_final_newline = original_text.endswith("\\n")
    full = original_text.splitlines()
    body = section.group(2)
    body_lines = body.splitlines()
    hunks = []
    current = None

    for line in body_lines:
        if line.startswith("@@"):
            if current is not None:
                hunks.append(current)
            current = []
        elif current is not None:
            if line.startswith((" ", "-", "+")):
                current.append(line)
            elif line.startswith("\\\\"):
                continue
            else:
                raise SystemExit(f"unsupported patch line in {rel}: {line!r}")
    if current is not None:
        hunks.append(current)

    for hunk in hunks:
        old = [line[1:] for line in hunk if line.startswith((" ", "-"))]
        new = [line[1:] for line in hunk if line.startswith((" ", "+"))]
        matches = [
            i for i in range(len(full) - len(old) + 1)
            if full[i:i + len(old)] == old
        ]
        if len(matches) != 1:
            raise SystemExit(
                f"context mismatch in {rel}: expected one match, got {len(matches)}"
            )
        start = matches[0]
        full[start:start + len(old)] = new

    new_text = "\\n".join(full)
    if had_final_newline:
        new_text += "\\n"
    path.write_text(new_text, encoding="utf-8", newline="")

print(f"updated {len(sections)} file(s)")
`;
