/*
 * VelaWear Agent - LLM Client
 *
 * Manages LLM inference requests via velaclaw_client.
 *
 * Author: pjjuihj
 * Team: 329 - dela
 */

#include <nuttx/config.h>
#include <string.h>
#include <stdio.h>
#include <syslog.h>

#include "velawear.h"

/****************************************************************************
 * Public Functions
 ****************************************************************************/

int velawear_llm_init(velawear_llm_t *llm)
{
  if (llm == NULL)
    {
      return VELAWEAR_ERR_INVAL;
    }

  memset(llm, 0, sizeof(velawear_llm_t));

  strncpy(llm->model_name, "mimo", sizeof(llm->model_name) - 1);
  llm->initialized = true;
  llm->connected = false;
  llm->request_count = 0;

  syslog(LOG_INFO, "[LLM] Initialized (local fallback ready)\n");
  return VELAWEAR_OK;
}

void velawear_llm_cleanup(velawear_llm_t *llm)
{
  if (llm == NULL)
    {
      return;
    }

  llm->initialized = false;
  llm->connected = false;
  syslog(LOG_INFO, "[LLM] Cleaned up\n");
}

int velawear_llm_request(velawear_llm_t *llm, const char *prompt,
                         char *response, size_t response_size)
{
  if (llm == NULL || !llm->initialized || prompt == NULL ||
      response == NULL || response_size == 0)
    {
      return VELAWEAR_ERR_INVAL;
    }

  llm->request_count++;

  /* The contest image has no cloud transport or credentials.  Keep the
   * Agent action usable offline with deterministic local advice instead of
   * silently dropping a CALL_LLM action. */
  if (strstr(prompt, "水") != NULL || strstr(prompt, "喝") != NULL)
    {
      snprintf(response, response_size, "本地建议：现在补充水分");
    }
  else if (strstr(prompt, "休息") != NULL)
    {
      snprintf(response, response_size, "本地建议：休息片刻再继续");
    }
  else if (strstr(prompt, "活动") != NULL)
    {
      snprintf(response, response_size, "本地建议：起来活动一下");
    }
  else
    {
      snprintf(response, response_size, "本地建议：保持活动并注意状态");
    }

  syslog(LOG_INFO, "[LLM] request=%d local_fallback connected=%d\n",
         llm->request_count, llm->connected ? 1 : 0);
  return VELAWEAR_OK;
}
