/* VelaWear Agent - compact BLE Agent protocol */
#ifndef __VELAWEAR_AGENT_PROTOCOL_H
#define __VELAWEAR_AGENT_PROTOCOL_H

#include <stdbool.h>
#include <stdint.h>

#define VELAWEAR_AGENT_PROTOCOL_VERSION       1
#define VELAWEAR_AGENT_EVENT_FRAME_SIZE       11
