/*
 * VelaWear Agent - Audio Sensor Driver
 *
 * The Huangshan Pi has an onboard MEMS microphone wired to the SF32LB52
 * AUDCODEC ADC.  The board port has no /dev/audio/pcm_in0 node, so this
 * driver owns the direct AUDCODEC circular-DMA stream.
 */

#include <nuttx/config.h>
#include <string.h>
#include <unistd.h>
#include <syslog.h>
#include <time.h>

#include "velawear.h"
#include "../audio_hw_test.h"

#define AUDIO_LEVEL_START_THRESHOLD 500U
#define AUDIO_LEVEL_STOP_THRESHOLD  300U
#define AUDIO_LEVEL_DEBOUNCE_HALVES 3U
#define AUDIO_STREAM_START_GRACE_MS 500U

static uint32_t audio_sensor_now_ms(void)
{
  struct timespec ts;

  if (clock_gettime(CLOCK_MONOTONIC, &ts) != 0)
    {
      return (uint32_t)time(NULL) * 1000U;
    }

  return (uint32_t)(ts.tv_sec * 1000U + ts.tv_nsec / 1000000U);
}

static void audio_sensor_push_event(velawear_audio_t *audio,
                                    bool active,
                                    uint32_t avg_abs,
                                    uint32_t peak_abs)
{
  velawear_events_t *events;
  velawear_event_t event;

  if (audio == NULL || audio->events == NULL)
    {
      return;
    }

  events = (velawear_events_t *)audio->events;
  memset(&event, 0, sizeof(event));
  event.type = VELAWEAR_EVENT_AUDIO;
  event.priority = VELAWEAR_PRIORITY_NORMAL;
  event.timestamp = audio_sensor_now_ms();
  event.data.audio.active = active;
  event.data.audio.avg_abs = avg_abs;
  event.data.audio.peak_abs = peak_abs;
  if (active)
    {
      strncpy(event.data.audio.text, "sound_start",
              sizeof(event.data.audio.text) - 1);
    }
  else
    {
      strncpy(event.data.audio.text, "sound_end",
              sizeof(event.data.audio.text) - 1);
    }
  event.data.audio.length = (int)strlen(event.data.audio.text);

  if (event_manager_push(events, &event) < 0)
    {
      syslog(LOG_WARNING, "[AudioStream] audio event queue full\n");
    }
}

static void *audio_sensor_thread(void *context)
{
  velawear_audio_t *audio = (velawear_audio_t *)context;
  uint32_t start_ms = audio_sensor_now_ms();
  uint32_t last_report_ms = start_ms;
  uint32_t active_streak = 0;
  uint32_t silent_streak = 0;
  bool stream_has_samples = false;

  syslog(LOG_INFO, "[AudioStream] level worker started\n");
  while (audio->stream_running)
    {
      uint32_t avg_abs;
      uint32_t peak_abs;
      int ret = velawear_mic_stream_read_level(&avg_abs, &peak_abs);

      if (ret < 0)
        {
          syslog(LOG_ERR, "[AudioStream] level read failed\n");
          break;
        }

      if (ret > 0)
        {
          uint32_t now_ms = audio_sensor_now_ms();
          bool previous_active;
          bool current_active;

          /* DMA is restarted after playback.  Do not interpret its first
           * samples as microphone activity: DAC residue reaches the ADC
           * briefly even when the external PA is disabled. */
          if (!stream_has_samples)
            {
              stream_has_samples = true;
              start_ms = now_ms;
              active_streak = 0;
              silent_streak = 0;
              audio->level_active = false;
            }

          previous_active = audio->level_active;
          current_active = previous_active;

          if (!previous_active)
            {
              silent_streak = 0;
              if (avg_abs >= AUDIO_LEVEL_START_THRESHOLD)
                {
                  active_streak++;
                }
              else
                {
                  active_streak = 0;
                }

              if (now_ms - start_ms >= AUDIO_STREAM_START_GRACE_MS &&
                  active_streak >= AUDIO_LEVEL_DEBOUNCE_HALVES)
                {
                  current_active = true;
                  active_streak = 0;
                }
            }
          else
            {
              active_streak = 0;
              if (avg_abs <= AUDIO_LEVEL_STOP_THRESHOLD)
                {
                  silent_streak++;
                }
              else
                {
                  silent_streak = 0;
                }

              if (silent_streak >= AUDIO_LEVEL_DEBOUNCE_HALVES)
                {
                  current_active = false;
                  silent_streak = 0;
                }
            }

          audio->latest_avg_abs = avg_abs;
          audio->latest_peak_abs = peak_abs;
          audio->level_active = current_active;

          if (current_active != previous_active)
            {
              syslog(LOG_INFO,
                     "[AudioStream] sound %s avg_abs=%lu peak_abs=%lu\n",
                     current_active ? "start" : "end",
                     (unsigned long)avg_abs, (unsigned long)peak_abs);
              audio_sensor_push_event(audio, current_active, avg_abs,
                                      peak_abs);
              last_report_ms = now_ms;
            }
          else if (now_ms - last_report_ms >= 5000U)
            {
              syslog(LOG_INFO,
                     "[AudioStream] level avg_abs=%lu peak_abs=%lu active=%d\n",
                     (unsigned long)avg_abs, (unsigned long)peak_abs,
                     current_active ? 1 : 0);
              last_report_ms = now_ms;
            }
        }
      else
        {
          /* Playback owns the codec.  The next ready half starts a fresh
           * debounce window after microphone DMA is resumed. */
          stream_has_samples = false;
          active_streak = 0;
          silent_streak = 0;
        }

      usleep(10000);
    }

  audio->stream_running = false;
  syslog(LOG_INFO, "[AudioStream] level worker stopped\n");
  return NULL;
}

int audio_sensor_init(velawear_audio_t *audio)
{
  int ret;

  if (audio == NULL)
    {
      return VELAWEAR_ERR_INVAL;
    }

  memset(audio, 0, sizeof(velawear_audio_t));
  audio->fd = -1;
  audio->sample_rate = 16000;

  syslog(LOG_INFO,
         "[Audio] Probing onboard MEMS microphone via direct AUDCODEC ADC\n");
  ret = velawear_mic_hw_test();
  if (ret != 0)
    {
      syslog(LOG_WARNING,
             "[Audio] Onboard MEMS microphone ADC probe failed: %d\n", ret);
      return VELAWEAR_ERR_IO;
    }

  audio->initialized = true;
  syslog(LOG_INFO,
         "[Audio] Onboard MEMS microphone ready via direct AUDCODEC ADC at %d Hz\n",
         audio->sample_rate);
  return VELAWEAR_OK;
}

int audio_sensor_start(velawear_audio_t *audio, void *events)
{
  int ret;

  if (audio == NULL || !audio->initialized)
    {
      return VELAWEAR_ERR_IO;
    }
  if (audio->thread_started || audio->stream_running)
    {
      return VELAWEAR_ERR_BUSY;
    }

  ret = velawear_mic_stream_start();
  if (ret < 0)
    {
      return VELAWEAR_ERR_IO;
    }

  audio->events = events;
  audio->level_active = false;
  audio->latest_avg_abs = 0;
  audio->latest_peak_abs = 0;
  audio->stream_running = true;
  ret = pthread_create(&audio->thread, NULL, audio_sensor_thread, audio);
  if (ret != 0)
    {
      audio->stream_running = false;
      velawear_mic_stream_stop();
      syslog(LOG_ERR, "[AudioStream] level worker start failed: %d\n", ret);
      return VELAWEAR_ERR_IO;
    }

  audio->thread_started = true;
  return VELAWEAR_OK;
}

void audio_sensor_cleanup(velawear_audio_t *audio)
{
  if (audio == NULL)
    {
      return;
    }

  audio->stream_running = false;
  if (audio->thread_started)
    {
      pthread_join(audio->thread, NULL);
      audio->thread_started = false;
    }

  velawear_mic_stream_stop();
  if (audio->fd >= 0)
    {
      close(audio->fd);
      audio->fd = -1;
    }

  audio->events = NULL;
  audio->initialized = false;
  syslog(LOG_INFO, "[Audio] Cleaned up\n");
}
/*
 * VelaWear Agent - IMU Sensor Driver Implementation
 *
 * Reads LSM6DSL IMU data for motion detection.
 *
 * Author: pjjuihj
 * Team: 329 - dela
 */

#include <nuttx/config.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <errno.h>
#include <syslog.h>
#include <sys/ioctl.h>
#include <math.h>
#include <time.h>

#include "velawear.h"
#include "imu_sensor.h"

/****************************************************************************
 * Pre-processor Definitions
 ****************************************************************************/

/* The Huangshan Pi board registers the LSM6DSL as /dev/lsm6dsl0. */
#define IMU_DEVICE_PATH         "/dev/lsm6dsl0"

/* Motion thresholds are based on dynamic acceleration in g. */

#define DEFAULT_MOVE_THRESHOLD  0.15f
#define DEFAULT_RUN_THRESHOLD   0.35f
#define DEFAULT_FALL_THRESHOLD  15.0f

#define GRAVITY_FILTER_ALPHA    0.05f

#define FALL_FREEFALL_THRESHOLD 0.5f
#define FALL_IMPACT_THRESHOLD   8.0f
#define FALL_REST_MIN           0.7f
#define FALL_REST_MAX           1.3f
#define FALL_FREEFALL_WINDOW_MS 500
#define FALL_FREEFALL_MIN_MS    100
#define FALL_IMPACT_WINDOW_MS   2000
#define FALL_CONFIRM_HOLD_MS    2000

/****************************************************************************
 * Private Functions
 ****************************************************************************/

static float calculate_magnitude(float x, float y, float z)
{
  return sqrtf(x * x + y * y + z * z);
}

static uint32_t imu_now_ms(void)
{
  struct timespec ts;

  if (clock_gettime(CLOCK_MONOTONIC, &ts) != 0)
    {
      return (uint32_t)time(NULL) * 1000;
    }

  return (uint32_t)(ts.tv_sec * 1000 + ts.tv_nsec / 1000000);
}

static void reset_fall_detector(imu_sensor_t *imu)
{
  imu->fall_detector.stage = FALL_STAGE_NONE;
  imu->fall_detector.stage_start_ms = 0;
  imu->fall_detector.confirmed = false;
}

static void update_fall_detector(imu_sensor_t *imu, float accel_mag)
{
  uint32_t now = imu_now_ms();
  uint32_t elapsed = now - imu->fall_detector.stage_start_ms;

  switch (imu->fall_detector.stage)
    {
      case FALL_STAGE_NONE:
        if (accel_mag < FALL_FREEFALL_THRESHOLD)
          {
            imu->fall_detector.stage = FALL_STAGE_FREEFALL;
            imu->fall_detector.stage_start_ms = now;
            imu->fall_detector.confirmed = false;
          }
        break;

      case FALL_STAGE_FREEFALL:
        if (accel_mag > FALL_IMPACT_THRESHOLD &&
            elapsed >= FALL_FREEFALL_MIN_MS &&
            elapsed <= FALL_FREEFALL_WINDOW_MS)
          {
            imu->fall_detector.stage = FALL_STAGE_IMPACT;
            imu->fall_detector.stage_start_ms = now;
          }
        else if (accel_mag >= FALL_FREEFALL_THRESHOLD ||
                 elapsed > FALL_FREEFALL_WINDOW_MS)
          {
            /* Freefall must remain below 0.5g until the impact sample. */
            reset_fall_detector(imu);
          }
        break;

      case FALL_STAGE_IMPACT:
        if (accel_mag >= FALL_REST_MIN && accel_mag <= FALL_REST_MAX &&
            elapsed <= FALL_IMPACT_WINDOW_MS)
          {
            imu->fall_detector.stage = FALL_STAGE_STILL;
            imu->fall_detector.stage_start_ms = now;
            imu->fall_detector.confirmed = true;
            syslog(LOG_WARNING,
                   "[IMU] Fall confirmed after freefall and impact\n");
          }
        else if (elapsed > FALL_IMPACT_WINDOW_MS)
          {
            reset_fall_detector(imu);
          }
        break;

      case FALL_STAGE_STILL:
        if (elapsed > FALL_CONFIRM_HOLD_MS)
          {
            reset_fall_detector(imu);
          }
        break;

      default:
        reset_fall_detector(imu);
        break;
    }

  imu->motion.fall_detected = imu->fall_detector.confirmed;
}

static void update_motion_state(imu_sensor_t *imu, imu_data_t *data)
{
  float accel_mag = calculate_magnitude(data->accel_x,
                                        data->accel_y,
                                        data->accel_z);
  float dynamic_x;
  float dynamic_y;
  float dynamic_z;
  float dynamic_mag;
  float gyro_mag = calculate_magnitude(data->gyro_x,
                                       data->gyro_y,
                                       data->gyro_z);

  /* Remove the slowly changing gravity vector before deciding activity.
   * A stationary board reports about 1g, which must not count as motion. */

  if (!imu->gravity_valid)
    {
      imu->gravity_x = data->accel_x;
      imu->gravity_y = data->accel_y;
      imu->gravity_z = data->accel_z;
      imu->gravity_valid = true;
    }
  else
    {
      imu->gravity_x += GRAVITY_FILTER_ALPHA *
                        (data->accel_x - imu->gravity_x);
      imu->gravity_y += GRAVITY_FILTER_ALPHA *
                        (data->accel_y - imu->gravity_y);
      imu->gravity_z += GRAVITY_FILTER_ALPHA *
                        (data->accel_z - imu->gravity_z);
    }

  dynamic_x = data->accel_x - imu->gravity_x;
  dynamic_y = data->accel_y - imu->gravity_y;
  dynamic_z = data->accel_z - imu->gravity_z;
  dynamic_mag = calculate_magnitude(dynamic_x, dynamic_y, dynamic_z);

  /* Confirm a fall only after freefall, impact, and post-impact stillness. */

  update_fall_detector(imu, accel_mag);

  /* Check for running (high acceleration + gyro) */

  if (dynamic_mag > imu->threshold_run && gyro_mag > 1.0f)
    {
      imu->motion.is_running = true;
      imu->motion.is_moving = true;
      imu->motion.last_motion_time = time(NULL);
      imu->motion.motion_count++;
    }
  /* Check for moving (moderate acceleration) */

  else if (dynamic_mag > imu->threshold_move)
    {
      imu->motion.is_moving = true;
      imu->motion.is_running = false;
      imu->motion.last_motion_time = time(NULL);
      imu->motion.motion_count++;
    }
  else
    {
      /* No significant motion */

      if (time(NULL) - imu->motion.last_motion_time > 5)
        {
          imu->motion.is_moving = false;
          imu->motion.is_running = false;
        }
    }

  imu->motion.motion_intensity = dynamic_mag;
}

/****************************************************************************
 * Public Functions
 ****************************************************************************/

int imu_sensor_init(imu_sensor_t *imu)
{
  memset(imu, 0, sizeof(imu_sensor_t));

  /* Open IMU device */

  imu->fd = open(IMU_DEVICE_PATH, O_RDONLY);
  if (imu->fd < 0)
    {
      syslog(LOG_ERR, "[IMU] Failed to open %s: %d\n",
             IMU_DEVICE_PATH, errno);
      return VELAWEAR_ERR_IO;
    }

  /* Start the sensor before requesting samples.  The LSM6DSL driver exposes
   * data through SNIOC_LSM6DSLSENSORREAD rather than read(). */
  if (ioctl(imu->fd, SNIOC_START, 0) < 0)
    {
      syslog(LOG_ERR, "[IMU] Failed to start %s: %d\n",
             IMU_DEVICE_PATH, errno);
      close(imu->fd);
      imu->fd = -1;
      return VELAWEAR_ERR_IO;
    }

  /* Set default thresholds */

  imu->threshold_move = DEFAULT_MOVE_THRESHOLD;
  imu->threshold_run = DEFAULT_RUN_THRESHOLD;
  imu->threshold_fall = DEFAULT_FALL_THRESHOLD;

  imu->initialized = true;
  imu->buffer_index = 0;

  syslog(LOG_INFO, "[IMU] Initialized\n");
  return VELAWEAR_OK;
}

void imu_sensor_cleanup(imu_sensor_t *imu)
{
  if (imu->fd >= 0)
    {
      close(imu->fd);
    }

  imu->initialized = false;
  syslog(LOG_INFO, "[IMU] Cleaned up\n");
}

