  int type;
  uint32_t priority;
  union
    {
      struct
        {
          char text[256];
        } display;
      struct
        {
          int duration_ms;
          int pattern;
        } vibrate;
      struct
        {
          char data[512];
          int length;
        } ble;
      struct
        {
          char prompt[1024];
        } llm;
      struct
        {
          uint32_t duration_ms;
          int id;
        } timer;
    } params;
} velawear_action_t;

/* Configuration structure */

typedef struct velawear_config
{
  int imu_sample_rate_hz;
  int sedentary_threshold_sec;
  float fall_accel_threshold_g;
  int event_queue_size;
  bool llm_enabled;
  bool ble_enabled;
} velawear_config_t;

/* LLM client structure */

typedef struct velawear_llm
{
  bool initialized;
  bool connected;
  char model_name[64];
  int request_count;
} velawear_llm_t;

/* Audio sensor structure */

typedef struct velawear_audio
{
  int fd;
  bool initialized;
  int sample_rate;
  pthread_t thread;
  bool thread_started;
  volatile bool stream_running;
  void *events;
  bool level_active;
  uint32_t latest_avg_abs;
