   259	static ssize_t velawear_ble_write_llm_response(
   260	    struct bt_conn *conn, const struct bt_gatt_attr *attr, const void *buf,
   261	    uint16_t len, uint16_t offset, uint8_t flags)
   262	{
   263	  velawear_agent_llm_response_t response;
   264	
   265	  (void)conn;
   266	  (void)attr;
   267	  if (buf == NULL || offset != 0 ||
   268	      (flags & BT_GATT_WRITE_FLAG_PREPARE) != 0 ||
   269	      velawear_agent_decode_llm_response((const uint8_t *)buf, len,
   270	                                         &response) < 0)
   271	    {
   272	      return -EINVAL;
   273	    }
   274	
   275	  pthread_mutex_lock(&g_lock);
   276	  if (!g_initialized || !g_llm_waiting ||
   277	      response.sequence != g_llm_pending_sequence)
   278	    {
   279	      pthread_mutex_unlock(&g_lock);
   280	      return -EALREADY;
   281	    }
   282	
   283	  g_llm_response_status = response.status;
   284	  g_llm_response_length = response.length;
   285	  memcpy(g_llm_response_text, response.text,
   286	         sizeof(g_llm_response_text));
   287	  g_llm_waiting = false;
   288	  pthread_mutex_unlock(&g_lock);
   289	
   290	  k_sem_give(&g_llm_response_sem);
   291	  syslog(LOG_INFO, "[BLE] LLM response accepted: seq=%u status=%u bytes=%u\n",
   292	         (unsigned int)response.sequence, (unsigned int)response.status,
   293	         (unsigned int)response.length);
   294	  return len;
   295	}
