   297	static ssize_t velawear_ble_write_agent_command(
   298	    struct bt_conn *conn, const struct bt_gatt_attr *attr, const void *buf,
   299	    uint16_t len, uint16_t offset, uint8_t flags)
   300	{
   301	  const uint8_t *data = (const uint8_t *)buf;
   302	  velawear_agent_command_t command;
   303	  velawear_event_t event;
   304	  int ret;
   305	
   306	  (void)conn;
   307	  (void)attr;
   308	  if (buf == NULL || offset != 0 ||
   309	      (flags & BT_GATT_WRITE_FLAG_PREPARE) != 0 ||
   310	      velawear_agent_decode_command(data, len, &command) < 0)
   311	    {
   312	      return -EINVAL;
   313	    }
   314	
   315	  pthread_mutex_lock(&g_lock);
   316	  if (g_events == NULL ||
   317	      (g_have_last_agent_command_sequence &&
   318	       !velawear_agent_command_sequence_is_newer(
   319	           command.sequence, g_last_agent_command_sequence)))
   320	    {
   321	      pthread_mutex_unlock(&g_lock);
   322	      return -EALREADY;
   323	    }
   324	
   325	  g_last_agent_command_sequence = command.sequence;
   326	  g_have_last_agent_command_sequence = true;
   327	  pthread_mutex_unlock(&g_lock);
   328	
   329	  memset(&event, 0, sizeof(event));
   330	  event.type = VELAWEAR_EVENT_BLE_MSG;
   331	  event.priority = VELAWEAR_PRIORITY_HIGH;
   332	  event.data.ble.length = len;
   333	  memcpy(event.data.ble.data, data, len);
   334	  ret = event_manager_push(g_events, &event);
   335	  if (ret < 0)
   336	    {
   337	      syslog(LOG_WARNING, "[BLE] Agent command queue full: %d\n", ret);
   338	      return BT_GATT_ERR(BT_ATT_ERR_INSUFFICIENT_RESOURCES);
   339	    }
   340	
   341	  syslog(LOG_INFO, "[BLE] Agent command queued: seq=%u id=%u\n",
   342	         (unsigned int)command.sequence, (unsigned int)command.command_id);
   343	  return len;
   344	}
