   397	static void velawear_ble_notify_current_status(void)
   398	{
   399	  uint8_t value[3];
   400	  struct bt_conn *conn;
   401	
   402	  pthread_mutex_lock(&g_lock);
   403	  value[0] = (uint8_t)g_motion_type;
   404	  value[1] = g_intensity_percent;
   405	  value[2] = g_alert_active ? 1 : 0;
   420	                                            const uint8_t *frame,
   421	                                            uint16_t frame_size)
   422	{
   423	  bool notify_enabled;
   424	  struct bt_conn *notify_conn;
   425	  struct bt_conn *conn;
   426	  int ret;
   427	
   428	  pthread_mutex_lock(&g_lock);
   429	  if (attr_index == VELAWEAR_BLE_AGENT_EVENT_ATTR_INDEX)
   430	    {
   431	      notify_enabled = g_agent_event_notify_enabled;
   432	      notify_conn = g_agent_event_notify_conn;
   433	    }
   434	  else if (attr_index == VELAWEAR_BLE_AGENT_RESULT_ATTR_INDEX)
   435	    {
   436	      notify_enabled = g_agent_result_notify_enabled;
   437	      notify_conn = g_agent_result_notify_conn;
   438	    }
   439	  else
   440	    {
   441	      pthread_mutex_unlock(&g_lock);
   442	      return VELAWEAR_ERR_INVAL;
   443	    }
   444	
   445	  conn = notify_enabled && notify_conn != NULL ? bt_conn_ref(notify_conn) : NULL;
   446	  pthread_mutex_unlock(&g_lock);
   447	  if (conn == NULL)
   448	    {
   449	      return VELAWEAR_OK;
   450	    }
   451	
   452	  ret = bt_gatt_notify(conn, &attr_velawear_svc[attr_index], frame, frame_size);
   453	  bt_conn_unref(conn);
   454	  if (ret < 0)
   455	    {
   456	      syslog(LOG_WARNING, "[BLE] Agent notification failed: %d\n", ret);
   457	      return ret;
   458	    }
   459	
   460	  return VELAWEAR_OK;
   461	}
