   483	int velawear_ble_publish_agent_event(const velawear_event_t *event)
   484	{
   485	  velawear_agent_event_t agent_event;
   486	  uint8_t frame[VELAWEAR_AGENT_EVENT_FRAME_SIZE];
   487	  int ret;
   488	
   489	  if (event == NULL || !g_initialized)
   490	    {
   491	      return VELAWEAR_ERR_INVAL;
   492	    }
   493	
   494	  memset(&agent_event, 0, sizeof(agent_event));
   495	  switch (event->type)
   496	    {
   497	      case VELAWEAR_EVENT_MOTION:
   498	        agent_event.event_type = VELAWEAR_AGENT_EVENT_MOTION;
   499	        agent_event.intensity_percent =
   500	            velawear_ble_percent_from_intensity(event->data.motion.intensity);
   501	        break;
   502	
   503	      case VELAWEAR_EVENT_FALL:
   504	        agent_event.event_type = VELAWEAR_AGENT_EVENT_FALL;
   505	        agent_event.priority = VELAWEAR_AGENT_PRIORITY_CRITICAL;
   506	        agent_event.intensity_percent = 100;
   507	        break;
   508	
   509	      case VELAWEAR_EVENT_AUDIO:
   510	        agent_event.event_type = VELAWEAR_AGENT_EVENT_AUDIO;
   511	        agent_event.intensity_percent = event->data.audio.active ? 100 : 0;
   512	        agent_event.value = velawear_ble_u16_saturate(event->data.audio.avg_abs);
   513	        agent_event.peak = velawear_ble_u16_saturate(event->data.audio.peak_abs);
   514	        if (event->data.audio.active)
   515	          {
   516	            agent_event.flags |= VELAWEAR_AGENT_EVENT_FLAG_ACTIVE;
   517	          }
   518	        break;
   519	
   520	      case VELAWEAR_EVENT_TIMER:
   521	        agent_event.event_type = VELAWEAR_AGENT_EVENT_SEDENTARY;
   522	        break;
   523	
   524	      default:
   525	        return VELAWEAR_ERR_NOSUPPORT;
   526	    }
   527	
   528	  pthread_mutex_lock(&g_lock);
   529	  agent_event.sequence = g_agent_event_sequence++;
   530	  if (g_alert_active)
   531	    {
   532	      agent_event.flags |= VELAWEAR_AGENT_EVENT_FLAG_ALERT;
   533	    }
   534	
   535	  ret = velawear_agent_encode_event(&agent_event, frame, sizeof(frame));
   536	  pthread_mutex_unlock(&g_lock);
   537	  if (ret < 0)
   538	    {
   539	      return ret;
   540	    }
   541	
   542	  return velawear_ble_notify_agent_packet(VELAWEAR_BLE_AGENT_EVENT_ATTR_INDEX,
   543	                                          frame, (uint16_t)ret);
   544	}
