static void display_set_label_text(lv_obj_t *label, const char *text)
{
  const char *current;

  if (label == NULL || text == NULL)
    {
      return;
    }

  current = lv_label_get_text(label);
  if (current != NULL && strcmp(current, text) == 0)
    {
      return;
    }

  lv_label_set_text(label, text);
}

