import unittest

from velawear_agent_gateway import (
    COMMAND_RESULT_OK,
    decode_message,
    encode_message,
    COMMAND_SHOW_REMINDER,
    COMMAND_SET_SEDENTARY_THRESHOLD,
    EVENT_FALL,
    decode_event,
    decode_result,
    encode_command,
)


class AgentGatewayProtocolTest(unittest.TestCase):
    def test_decodes_fall_event(self):
        event = decode_event(bytes.fromhex("0103341203640700090001"))

        self.assertEqual(event["type"], EVENT_FALL)
        self.assertEqual(event["sequence"], 0x1234)
        self.assertEqual(event["priority"], 3)
        self.assertTrue(event["alert"])

    def test_encodes_threshold_command(self):
        frame = encode_command(COMMAND_SET_SEDENTARY_THRESHOLD, 0x1234, 300)

        self.assertEqual(frame.hex(), "010234122c01")

    def test_rejects_invalid_threshold(self):
        with self.assertRaises(ValueError):
            encode_command(COMMAND_SET_SEDENTARY_THRESHOLD, 1, 9)

    def test_encodes_and_decodes_message(self):
        frame = encode_message("fall detected", 0x1234, 3)
        message = decode_message(frame)

        self.assertEqual(message["sequence"], 0x1234)
        self.assertEqual(message["priority"], 3)
        self.assertEqual(message["text"], "fall detected")

    def test_rejects_oversized_message(self):
        with self.assertRaises(ValueError):
            encode_message("x" * 221, 1, 1)

    def test_decodes_command_result(self):
        result = decode_result(bytes.fromhex("0103341200"))

        self.assertEqual(result["command"], COMMAND_SHOW_REMINDER)
        self.assertEqual(result["sequence"], 0x1234)
        self.assertEqual(result["result"], COMMAND_RESULT_OK)


if __name__ == "__main__":
    unittest.main()

