static int sf32lb52_bt_forward_packet(struct sf32lb52_bt_priv_s *priv,
                                      uint8_t *data, size_t len)
{
  enum bt_buf_type_e type;
  int ret;

  if (len <= H4_HEADER_SIZE)
    {
      return -EINVAL;
    }

  switch (data[0])
    {
      case H4_EVT:
        sf32lb52_bt_normalize_event(data, len);
#if SF32LB52_BT_ERROR_TRACE
        if (len >= 4 && data[1] == 0x10)
          {
            syslog(LOG_WARNING,
                   "sf32lb52 bth4 hardware error: status=%02x\n",
                   data[3]);
