   166	int event_manager_start(velawear_events_t *events)
   167	{
   168	  int ret;
   169	
   170	  if (events->running)
   171	    {
   172	      return VELAWEAR_ERR_BUSY;
   173	    }
   174	
   175	  events->running = true;
   176	
   177	  ret = pthread_create(&events->thread, NULL, event_manager_thread, events);
   178	  if (ret != 0)
   179	    {
   180	      syslog(LOG_ERR, "[EventMgr] Failed to create thread: %d\n", ret);
   181	      events->running = false;
   182	      return VELAWEAR_ERR_IO;
   183	    }
   184	
   185	  syslog(LOG_INFO, "[EventMgr] Started\n");
   186	  return VELAWEAR_OK;
   187	}
