   206	      events->queue_open = false;
   207	    }
   208	
   209	  pthread_mutex_destroy(&events->pool_lock);
   210	  pthread_mutex_destroy(&events->lock);
   211	
   212	  syslog(LOG_INFO, "[EventMgr] Cleaned up\n");
   213	}
