   218	  int slot = -1;
   219	  int ret;
   220	
   221	  if (events == NULL || !events->queue_open || event == NULL)
   222	    {
   223	      return VELAWEAR_ERR_IO;
   224	    }
   225	
   226	  pthread_mutex_lock(&events->pool_lock);
   227	  /* Keep one pool slot for an Agent command.  Sensor producers must not
   228	   * prevent a connected BLE client from acknowledging or changing state. */
   229	  for (int i = 0; i < EVENT_POOL_SIZE - 1; i++)
   230	    {
   231	      if (!events->pool_used[i])
   232	        {
   233	          slot = i;
   234	          events->pool_used[i] = true;
   235	          memcpy(&events->pool[i], event, sizeof(*event));
   236	          break;
   237	        }
   238	    }
   239	
   240	  if (slot < 0 && event->type == VELAWEAR_EVENT_BLE_MSG &&
   241	      !events->pool_used[EVENT_POOL_SIZE - 1])
   242	    {
   243	      slot = EVENT_POOL_SIZE - 1;
   244	      events->pool_used[slot] = true;
   245	      memcpy(&events->pool[slot], event, sizeof(*event));
   246	    }
   247	  pthread_mutex_unlock(&events->pool_lock);
   248	
   249	  if (slot < 0)
   250	    {
   251	      return VELAWEAR_ERR_NOMEM;
   252	    }
   253	
   254	  /* The queue carries a stable pool slot, not a heap pointer. */
   255	  message = (uintptr_t)(slot + 1);
   256	  ret = file_mq_send(&events->queue, (const char *)&message,
   257	                     sizeof(message), event->priority);
   258	  if (ret < 0)
   259	    {
   260	      pthread_mutex_lock(&events->pool_lock);
   261	      events->pool_used[slot] = false;
   262	      pthread_mutex_unlock(&events->pool_lock);
   263	      syslog(LOG_WARNING, "[EventMgr] Failed to push event: %d\n", -ret);
   264	      return VELAWEAR_ERR_IO;
   265	    }
