   270	int event_manager_pop(velawear_events_t *events, velawear_event_t *event,
   271	                      int timeout_ms)
   272	{
   273	  struct timespec timeout;
   274	  uintptr_t message;
   275	  ssize_t nbytes;
   276	  int slot;
   277	
   278	  if (events == NULL || !events->queue_open || event == NULL)
   279	    {
   280	      return VELAWEAR_ERR_IO;
   281	    }
   282	
   283	  /* Calculate timeout */
   284	  clock_gettime(CLOCK_REALTIME, &timeout);
   285	  timeout.tv_sec += timeout_ms / 1000;
   286	  timeout.tv_nsec += (timeout_ms % 1000) * 1000000;
   287	  if (timeout.tv_nsec >= 1000000000)
   288	    {
   289	      timeout.tv_sec++;
   290	      timeout.tv_nsec -= 1000000000;
   291	    }
   292	
   293	  nbytes = file_mq_timedreceive(&events->queue, (char *)&message,
   294	                                sizeof(message), NULL, &timeout);
   295	  if (nbytes < 0)
   296	    {
   297	      if (nbytes == -ETIMEDOUT)
   298	        {
   299	          return VELAWEAR_ERR_TIMEOUT;
   300	        }
   301	
   302	      return VELAWEAR_ERR_IO;
   303	    }
   304	
   305	  if (nbytes != sizeof(message) || message == 0 ||
   306	      message > EVENT_POOL_SIZE)
   307	    {
   308	      return VELAWEAR_ERR_IO;
   309	    }
   310	
   311	  slot = (int)message - 1;
   312	  pthread_mutex_lock(&events->pool_lock);
   313	  if (!events->pool_used[slot])
   314	    {
   315	      pthread_mutex_unlock(&events->pool_lock);
   316	      return VELAWEAR_ERR_IO;
   317	    }
   318	
   319	  memcpy(event, &events->pool[slot], sizeof(*event));
   320	  events->pool_used[slot] = false;
   321	  pthread_mutex_unlock(&events->pool_lock);
   322	
   323	  return VELAWEAR_OK;
   324	}
