   337	      return VELAWEAR_ERR_NOMEM;
   338	    }
   339	
   340	  events->handlers[events->handler_count].event_type = event_type;
   341	  events->handlers[events->handler_count].handler = handler;
   342	  events->handlers[events->handler_count].context = context;
   343	  events->handlers[events->handler_count].priority = priority;
   344	  events->handler_count++;
