   276	static ssize_t velawear_ble_write_llm_response(
   277	    struct bt_conn *conn, const struct bt_gatt_attr *attr, const void *buf,
   278	    uint16_t len, uint16_t offset, uint8_t flags)
   279	{
   280	  velawear_agent_llm_response_t response;
   281	
   282	  (void)conn;
   283	  (void)attr;
   284	  if (buf == NULL || offset != 0 ||
   285	      (flags & BT_GATT_WRITE_FLAG_PREPARE) != 0 ||
   286	      velawear_agent_decode_llm_response((const uint8_t *)buf, len,
   287	                                         &response) < 0)
   288	    {
   289	      return -EINVAL;
   290	    }
   291	
   292	  pthread_mutex_lock(&g_lock);
   293	  if (!g_initialized || !g_llm_waiting ||
   294	      response.sequence != g_llm_pending_sequence)
   295	    {
   296	      pthread_mutex_unlock(&g_lock);
   297	      return -EALREADY;
   298	    }
   299	
   300	  g_llm_response_status = response.status;
   301	  g_llm_response_length = response.length;
   302	  memcpy(g_llm_response_text, response.text,
   303	         sizeof(g_llm_response_text));
   304	  g_llm_waiting = false;
   305	  pthread_mutex_unlock(&g_lock);
   306	
   307	  k_sem_give(&g_llm_response_sem);
   308	  syslog(LOG_INFO, "[BLE] LLM response accepted: seq=%u status=%u bytes=%u\n",
   309	         (unsigned int)response.sequence, (unsigned int)response.status,
   310	         (unsigned int)response.length);
   311	  return len;
   312	}
