   314	static ssize_t velawear_ble_write_agent_command(
   315	    struct bt_conn *conn, const struct bt_gatt_attr *attr, const void *buf,
   316	    uint16_t len, uint16_t offset, uint8_t flags)
   317	{
   318	  const uint8_t *data = (const uint8_t *)buf;
   319	  velawear_agent_command_t command;
   320	  velawear_event_t event;
   321	  int ret;
   322	
   323	  (void)conn;
   324	  (void)attr;
   325	  if (buf == NULL || offset != 0 ||
   326	      (flags & BT_GATT_WRITE_FLAG_PREPARE) != 0 ||
   327	      velawear_agent_decode_command(data, len, &command) < 0)
   328	    {
   329	      return -EINVAL;
   330	    }
   331	
   332	  pthread_mutex_lock(&g_lock);
   333	  if (g_events == NULL ||
   334	      (g_have_last_agent_command_sequence &&
   335	       !velawear_agent_command_sequence_is_newer(
   336	           command.sequence, g_last_agent_command_sequence)))
   337	    {
   338	      pthread_mutex_unlock(&g_lock);
   339	      return -EALREADY;
   340	    }
   341	
   342	  g_last_agent_command_sequence = command.sequence;
   343	  g_have_last_agent_command_sequence = true;
   344	  pthread_mutex_unlock(&g_lock);
   345	
   346	  memset(&event, 0, sizeof(event));
   347	  event.type = VELAWEAR_EVENT_BLE_MSG;
   348	  event.priority = VELAWEAR_PRIORITY_HIGH;
   349	  event.data.ble.length = len;
   350	  memcpy(event.data.ble.data, data, len);
   351	  ret = event_manager_push(g_events, &event);
   352	  if (ret < 0)
   353	    {
   354	      syslog(LOG_WARNING, "[BLE] Agent command queue full: %d\n", ret);
   355	      return BT_GATT_ERR(BT_ATT_ERR_INSUFFICIENT_RESOURCES);
   356	    }
   357	
   358	  syslog(LOG_INFO, "[BLE] Agent command queued: seq=%u id=%u\n",
   359	         (unsigned int)command.sequence, (unsigned int)command.command_id);
   360	  return len;
   361	}
