   513	int velawear_ble_publish_agent_event(const velawear_event_t *event)
   514	{
   515	  velawear_agent_event_t agent_event;
   516	  uint8_t frame[VELAWEAR_AGENT_EVENT_FRAME_SIZE];
   517	  int ret;
   518	
   519	  if (event == NULL || !g_initialized)
   520	    {
   521	      return VELAWEAR_ERR_INVAL;
   522	    }
   523	
   524	  memset(&agent_event, 0, sizeof(agent_event));
   525	  switch (event->type)
   526	    {
   527	      case VELAWEAR_EVENT_MOTION:
   528	        agent_event.event_type = VELAWEAR_AGENT_EVENT_MOTION;
   529	        agent_event.intensity_percent =
   530	            velawear_ble_percent_from_intensity(event->data.motion.intensity);
   531	        break;
   532	
   533	      case VELAWEAR_EVENT_FALL:
   534	        agent_event.event_type = VELAWEAR_AGENT_EVENT_FALL;
   535	        agent_event.priority = VELAWEAR_AGENT_PRIORITY_CRITICAL;
   536	        agent_event.intensity_percent = 100;
   537	        break;
   538	
   539	      case VELAWEAR_EVENT_AUDIO:
   540	        agent_event.event_type = VELAWEAR_AGENT_EVENT_AUDIO;
   541	        agent_event.intensity_percent = event->data.audio.active ? 100 : 0;
   542	        agent_event.value = velawear_ble_u16_saturate(event->data.audio.avg_abs);
   543	        agent_event.peak = velawear_ble_u16_saturate(event->data.audio.peak_abs);
   544	        if (event->data.audio.active)
   545	          {
   546	            agent_event.flags |= VELAWEAR_AGENT_EVENT_FLAG_ACTIVE;
   547	          }
   548	        break;
   549	
   550	      case VELAWEAR_EVENT_TIMER:
   551	        agent_event.event_type = VELAWEAR_AGENT_EVENT_SEDENTARY;
   552	        break;
   553	
   554	      default:
   555	        return VELAWEAR_ERR_NOSUPPORT;
   556	    }
   557	
   558	  pthread_mutex_lock(&g_lock);
   559	  agent_event.sequence = g_agent_event_sequence++;
   560	  if (g_alert_active)
   561	    {
   562	      agent_event.flags |= VELAWEAR_AGENT_EVENT_FLAG_ALERT;
   563	    }
   564	
   565	  ret = velawear_agent_encode_event(&agent_event, frame, sizeof(frame));
   566	  pthread_mutex_unlock(&g_lock);
   567	  if (ret < 0)
   568	    {
   569	      return ret;
   570	    }
   571	
   572	  return velawear_ble_notify_agent_packet(VELAWEAR_BLE_AGENT_EVENT_ATTR_INDEX,
   573	                                          frame, (uint16_t)ret);
   574	}
