   625	int velawear_ble_request_llm(const char *prompt, char *response,
   626	                              size_t response_size, uint32_t timeout_ms)
   627	{
   628	  uint8_t frame[VELAWEAR_AGENT_LLM_REQUEST_FRAME_MAX];
   629	  struct bt_conn *conn;
   630	  uint16_t sequence;
   631	  uint16_t response_length;
   632	  uint8_t response_status;
   633	  size_t copy_length;
   634	  int frame_size;
   635	  int ret;
   636	
   637	  if (prompt == NULL || response == NULL || response_size == 0 ||
   638	      timeout_ms == 0)
   639	    {
   640	      return -EINVAL;
   641	    }
   642	
   643	  frame_size = velawear_agent_encode_llm_request(
   644	      0, prompt, frame, sizeof(frame));
   645	  if (frame_size < 0)
   646	    {
   647	      return frame_size;
   648	    }
   649	
   650	  pthread_mutex_lock(&g_lock);
   651	  if (!g_initialized || !g_llm_request_notify_enabled ||
   652	      g_llm_request_notify_conn == NULL)
   653	    {
   654	      pthread_mutex_unlock(&g_lock);
   655	      return -ENOTCONN;
   656	    }
   657	
   658	  if (g_llm_waiting)
   659	    {
   660	      pthread_mutex_unlock(&g_lock);
   661	      return -EBUSY;
   662	    }
   663	
   664	  while (k_sem_take(&g_llm_response_sem, K_NO_WAIT) == 0)
   665	    {
   666	    }
   667	
   668	  sequence = g_llm_sequence++;
   669	  if (g_llm_sequence == 0)
   670	    {
   671	      g_llm_sequence = 1;
   672	    }
   673	
   674	  frame[2] = (uint8_t)(sequence & 0xff);
   675	  frame[3] = (uint8_t)(sequence >> 8);
   676	  g_llm_pending_sequence = sequence;
   677	  g_llm_response_status = VELAWEAR_AGENT_LLM_STATUS_ERROR;
   678	  g_llm_response_length = 0;
   679	  g_llm_response_text[0] = '\0';
   680	  g_llm_waiting = true;
   681	  conn = bt_conn_ref(g_llm_request_notify_conn);
   682	  pthread_mutex_unlock(&g_lock);
   683	
   684	  ret = bt_gatt_notify(conn,
   685	                       &attr_velawear_svc[VELAWEAR_BLE_LLM_REQUEST_ATTR_INDEX],
   686	                       frame, (uint16_t)frame_size);
   687	  bt_conn_unref(conn);
   688	  if (ret < 0)
   689	    {
   690	      pthread_mutex_lock(&g_lock);
   691	      if (g_llm_pending_sequence == sequence)
   692	        {
   693	          g_llm_waiting = false;
   694	        }
   695	      pthread_mutex_unlock(&g_lock);
   696	      syslog(LOG_WARNING, "[BLE] LLM request notify failed: %d\n", ret);
   697	      return ret;
   698	    }
   699	
   700	  ret = k_sem_take(&g_llm_response_sem, K_MSEC(timeout_ms));
   701	  if (ret < 0)
   702	    {
   703	      pthread_mutex_lock(&g_lock);
   704	      if (g_llm_pending_sequence == sequence)
   705	        {
   706	          g_llm_waiting = false;
   707	        }
   708	      pthread_mutex_unlock(&g_lock);
   709	      syslog(LOG_WARNING, "[BLE] LLM response timeout: seq=%u\n",
   710	             (unsigned int)sequence);
   711	      return -ETIMEDOUT;
   712	    }
   713	
   714	  pthread_mutex_lock(&g_lock);
   715	  response_status = g_llm_response_status;
   716	  response_length = g_llm_response_length;
   717	  copy_length = response_length < response_size - 1 ?
   718	                response_length : response_size - 1;
   719	  memcpy(response, g_llm_response_text, copy_length);
   720	  response[copy_length] = '\0';
   721	  pthread_mutex_unlock(&g_lock);
   722	
   723	  if (response_status != VELAWEAR_AGENT_LLM_STATUS_OK)
   724	    {
   725	      return -EIO;
   726	    }
   727	
   728	  return 0;
   729	}
