    {
      g_mic_stream_ready &= (uint8_t)~1U;
      offset = 0;
    }
  else if (ready & 2U)
    {
      g_mic_stream_ready &= (uint8_t)~2U;
      offset = AUDIO_MIC_STREAM_HALF_WORDS;
    }
  else
    {
      up_irq_restore(flags);
      pthread_mutex_unlock(&g_audio_hw_lock);
      return 0;
    }
  up_irq_restore(flags);

  for (uint32_t i = 0; i < AUDIO_MIC_STREAM_HALF_WORDS; i++)
