 937       syslog(LOG_ERR, "[VelaWear] Vibrate handler registration failed: %d\n",
 938              ret);
 939       return ret;
 940     }
 941 
 942   ret = action_manager_register_handler(&agent->actions,
 943                                         VELAWEAR_ACTION_PLAY_SOUND,
 944                                         velawear_play_sound_action_handler,
 945                                         agent);
 946   if (ret < 0)
 947     {
 948       syslog(LOG_ERR, "[VelaWear] Sound handler registration failed: %d\n",
 949              ret);
 950       return ret;
 951     }
 952 
 953   ret = action_manager_register_handler(&agent->actions,
 954                                         VELAWEAR_ACTION_SHOW_UI,
 955                                         velawear_show_ui_action_handler,
 956                                         agent);
 957   if (ret < 0)
 958     {
 959       syslog(LOG_ERR, "[VelaWear] Show UI handler registration failed: %d\n",
 960              ret);
 961       return ret;
 962     }
 963 
 964   ret = action_manager_register_handler(&agent->actions,
 965                                         VELAWEAR_ACTION_SEND_BLE,
 966                                         velawear_send_ble_action_handler,
 967                                         agent);
 968   if (ret < 0)
 969     {
 970       syslog(LOG_ERR, "[VelaWear] BLE handler registration failed: %d\n",
 971              ret);
 972       return ret;
 973     }
 974 
 975   ret = action_manager_register_handler(&agent->actions,
 976                                         VELAWEAR_ACTION_CALL_LLM,
 977                                         velawear_call_llm_action_handler,
 978                                         agent);
 979   if (ret < 0)
 980     {
 981       syslog(LOG_ERR, "[VelaWear] LLM handler registration failed: %d\n",
 982              ret);
 983       return ret;
 984     }
 985 
 986   ret = action_manager_register_handler(&agent->actions,
 987                                         VELAWEAR_ACTION_SET_TIMER,
 988                                         velawear_set_timer_action_handler,
 989                                         agent);
 990   if (ret < 0)
 991     {
 992       syslog(LOG_ERR, "[VelaWear] Timer handler registration failed: %d\n",
 993              ret);
 994       return ret;
 995     }
 996 
 997   ret = pthread_mutex_init(&agent->timer_lock, NULL);
 998   if (ret != 0)
 999     {
1000       syslog(LOG_ERR, "[VelaWear] Timer lock init failed: %d\n", ret);
1001       return VELAWEAR_ERR_IO;
1002     }
1003   agent->timer_lock_initialized = true;
1004 
1005   return VELAWEAR_OK;
1006 }
