1008 static int velawear_start(velawear_agent_t *agent)
1009 {
1010   int ret;
1011 
1012   /* The main loop owns event queue consumption.  Do not start a second
1013    * consumer thread for the same mqueue. */
1014 
1015   /* Start action manager thread. */
1016 
1017   ret = action_manager_start(&agent->actions);
1018   if (ret < 0)
1019     {
1020       syslog(LOG_ERR, "[VelaWear] Action manager start failed: %d\n", ret);
1021       return ret;
1022     }
1023 
1024   /* Decision rules use both event-driven evaluation and a real-state
1025    * periodic worker so inactivity can cross its threshold without another
1026    * motion edge. */
1027   agent->running = true;
1028   agent->started_ms = velawear_now_ms();
1029   ret = decision_engine_start(&agent->engine);
1030   if (ret < 0)
1031     {
1032       agent->running = false;
1033       syslog(LOG_ERR, "[VelaWear] Decision engine start failed: %d\n", ret);
1034       return ret;
1035     }
1036 
1037   /* Mark agent as running before starting the sensor producer. */
1038 
1039   ret = velawear_watchdog_start(agent);
1040   if (ret < 0)
1041     {
1042       agent->running = false;
1043       return ret;
1044     }
1045 
1046   if (agent->audio.initialized)
1047     {
1048       ret = audio_sensor_start(&agent->audio, &agent->events);
1049       if (ret < 0)
1050         {
1051           agent->audio_available = false;
1052           syslog(LOG_WARNING,
1053                  "[VelaWear] Continuous microphone start failed: %d\n", ret);
1054         }
1055     }
1056 
1057   if (agent->imu.initialized)
1058     {
1059       ret = pthread_create(&agent->imu_thread, NULL,
1060                            velawear_imu_thread, agent);
1061       if (ret != 0)
1062         {
1063           agent->running = false;
1064           syslog(LOG_ERR, "[VelaWear] IMU thread start failed: %d\n", ret);
1065           return VELAWEAR_ERR_IO;
1066         }
1067       agent->imu_thread_started = true;
1068     }
1069   return VELAWEAR_OK;
1070 }
1071 
1072 static void velawear_cleanup(velawear_agent_t *agent)
1073 {
1074   /* Stop subsystems in reverse order */
1075 
1076   agent->running = false;
1077   velawear_watchdog_stop(agent);
1078   if (agent->imu_thread_started)
1079     {
1080       pthread_join(agent->imu_thread, NULL);
1081       agent->imu_thread_started = false;
1082     }
1083 
1084   audio_sensor_cleanup(&agent->audio);
1085   velawear_llm_cleanup(&agent->llm);
1086   velawear_ble_cleanup();
1087   imu_sensor_cleanup(&agent->imu);
1088   /* Stop the periodic decision worker before destroying the managers it
1089    * references. */
1090   decision_engine_cleanup(&agent->engine);
1091   action_manager_cleanup(&agent->actions);
1092   event_manager_cleanup(&agent->events);
1093   velawear_buttons_close();
1094   display_manager_cleanup(&agent->display);
1095   state_manager_cleanup(&agent->state_mgr);
1096   velawear_config_cleanup(&agent->config);
1097   if (agent->timer_lock_initialized)
1098     {
1099       pthread_mutex_destroy(&agent->timer_lock);
1100       agent->timer_lock_initialized = false;
1101     }
1102 }
