1110 static int velawear_event_handler(velawear_event_t *event, void *context)
1111 {
1112   velawear_agent_t *agent = (velawear_agent_t *)context;
1113   velawear_state_t state;
1114   velawear_action_t action;
1115   int rule_id;
1116   int ret;
1117 
1118   if (event->type == VELAWEAR_EVENT_BLE_MSG)
1119     {
1120       return velawear_handle_agent_command(agent, event);
1121     }
1122 
1123   if (event->type == VELAWEAR_EVENT_AUDIO)
1124     {
1125       syslog(LOG_INFO,
1126              "[Audio] event=%s avg_abs=%lu peak_abs=%lu active=%d\n",
1127              event->data.audio.text,
1128              (unsigned long)event->data.audio.avg_abs,
1129              (unsigned long)event->data.audio.peak_abs,
1130              event->data.audio.active ? 1 : 0);
1131     }
1132 
1133   ret = state_manager_update_from_event(&agent->state_mgr, event);
1134   if (ret < 0)
1135     {
1136       return ret;
1137     }
1138 
1139   state = state_manager_get_state(&agent->state_mgr);
1140   agent->state = state;
1141   velawear_publish_agent_event(agent, event);
1142   rule_id = decision_engine_evaluate(&agent->engine, &state, event);
1143 
1144   /* Every matched rule produces a traceable action.  Rule-specific handlers
1145    * can replace this log action later without changing the event pipeline. */
1146   if (rule_id >= 0 && event->type != VELAWEAR_EVENT_MOTION &&
1147       event->type != VELAWEAR_EVENT_FALL)
1148     {
1149       memset(&action, 0, sizeof(action));
1150       action.type = VELAWEAR_ACTION_LOG;
1151       action.priority = event->priority;
1152       ret = action_manager_execute(&agent->actions, &action);
1153       if (ret < 0)
1154         {
1155           return ret;
1156         }
1157     }
1158 
1159   /* The action manager worker performs callbacks; wake it after evaluation. */
1160   return action_manager_process(&agent->actions);
1161 }
