1163 static void velawear_publish_agent_event(velawear_agent_t *agent,
1164                                          const velawear_event_t *event)
1165 {
1166   static int last_motion_type = -1;
1167   int ret;
1168 
1169   if (agent == NULL || event == NULL || !agent->ble_available)
1170     {
1171       return;
1172     }
1173 
1174   if (event->type == VELAWEAR_EVENT_MOTION)
1175     {
1176       if (event->data.motion.motion_type == last_motion_type)
1177         {
1178           return;
1179         }
1180 
1181       last_motion_type = event->data.motion.motion_type;
1182     }
1183   else if (event->type != VELAWEAR_EVENT_FALL &&
1184            event->type != VELAWEAR_EVENT_AUDIO &&
1185            event->type != VELAWEAR_EVENT_TIMER)
1186     {
1187       return;
1188     }
1189 
1190   ret = velawear_ble_publish_agent_event(event);
1191   if (ret < 0)
1192     {
1193       syslog(LOG_WARNING, "[BLE] Age…177 tokens truncated…< 0)
1210     {
1211       syslog(LOG_WARNING, "[BLE] Invalid queued Agent command\n");
1212       return VELAWEAR_OK;
1213     }
1214 
1215   switch (command.command_id)
1216     {
1217       case VELAWEAR_AGENT_COMMAND_ACK_ALERT:
1218         display_manager_clear_alert(&agent->display);
1219         velawear_ble_set_alert(false);
1220         result = VELAWEAR_AGENT_COMMAND_RESULT_OK;
1221         break;
1222 
1223       case VELAWEAR_AGENT_COMMAND_SET_SEDENTARY_THRESHOLD:
1224         ret = velawear_ble_set_sedentary_threshold(command.argument);
1225         result = ret == VELAWEAR_OK ? VELAWEAR_AGENT_COMMAND_RESULT_OK :
1226                                       VELAWEAR_AGENT_COMMAND_RESULT_EXECUTION_FAILED;
1227         break;
1228 
1229       case VELAWEAR_AGENT_COMMAND_SHOW_REMINDER:
1230         if (command.argument == VELAWEAR_AGENT_REMINDER_HYDRATE)
1231           {
1232             message = "AI 建议：补充水分";
1233           }
1234         else if (command.argument == VELAWEAR_AGENT_REMINDER_REST)
1235           {
1236             message = "AI 建议：休息一下";
1237           }
1238         else
1239           {
1240             message = "AI 建议：起来活动一下";
1241           }
1242 
1243         memset(&action, 0, sizeof(action));
1244         action.type = VELAWEAR_ACTION_CALL_LLM;
1245         action.priority = VELAWEAR_PRIORITY_HIGH;
1246         snprintf(action.params.llm.prompt, sizeof(action.params.llm.prompt),
1247                  "%s", message);
1248         ret = action_manager_execute(&agent->actions, &action);
1249         result = ret == VELAWEAR_OK ?
1250                  VELAWEAR_AGENT_COMMAND_RESULT_OK :
1251                  VELAWEAR_AGENT_COMMAND_RESULT_EXECUTION_FAILED;
1252         break;
1253 
1254       default:
1255         break;
1256     }
1257 
1258   velawear_ble_report_agent_command_result(command.sequence, command.command_id,
1259                                            (uint8_t)result);
1260   syslog(LOG_INFO, "[BLE] Agent command handled: seq=%u id=%u result=%d\n",
1261          (unsigned int)command.sequence, (unsigned int)command.command_id,
1262          result);
1263   return VELAWEAR_OK;
1264 }
