 240 /****************************************************************************
 241  * Sedentary Reminder (Layer 1 - Configurable)
 242  ****************************************************************************/
 243 
 244 static uint32_t sedentary_threshold_sec(velawear_engine_t *engine)
 245 {
 246   if (engine != NULL && engine->config != NULL &&
 247       engine->config->sedentary_threshold_sec > 0)
 248     {
 249       return engine->config->sedentary_threshold_sec;
 250     }
 251 
 252   return 45 * 60;
 253 }
 254 
 255 static bool sedentary_condition(velawear_state_t *state,
 256                                 velawear_event_t *event,
 257                                 void *context)
 258 {
 259   velawear_engine_t *engine = (velawear_engine_t *)context;
 260   uint32_t now;
 261 
 262   if (event == NULL ||
 263       (event->type != VELAWEAR_EVENT_MOTION &&
 264        event->type != VELAWEAR_EVENT_TIMER) ||
 265       state == NULL || state->is_moving || state->last_move_time == 0)
 266     {
 267       return false;
 268     }
 269 
 270   now = (uint32_t)time(NULL);
 271   return now >= state->last_move_time &&
 272          now - state->last_move_time >= sedentary_threshold_sec(engine);
 273 }
 274 
 275 static int sedentary_action(velawear_state_t *state, void *context)
 276 {
 277   velawear_engine_t *engine = (velawear_engine_t *)context;
 278   velawear_action_t action;
 279   uint32_t now;
 280   uint32_t cooldown_sec = 5 * 60;
 281   int ret;
 282 
 283   if (engine == NULL || engine->actions == NULL)
 284     {
 285       return VELAWEAR_ERR_INVAL;
 286     }
 287 
 288   now = (uint32_t)time(NULL);
 289   if (engine->last_sedentary_reminder != 0 &&
 290       now >= engine->last_sedentary_reminder &&
 291       now - engine->last_sedentary_reminder < cooldown_sec)
 292     {
 293       return VELAWEAR_OK;
 294     }
 295 
 296   memset(&action, 0, sizeof(action));
 297   action.type = VELAWEAR_ACTION_SHOW_UI;
 298   action.priority = VELAWEAR_PRIORITY_NORMAL;
 299   snprintf(action.params.display.text, sizeof(action.params.display.text),
 300            "该活动一下了\n检测到持续静止");
 301 
 302   ret = action_manager_execute(engine->actions, &action);
 303   if (ret == VELAWEAR_OK)
 304     {
 305       engine->last_sedentary_reminder = now;
 306 
 307       /* The Huangshan Pi exposes an external speaker through its onboard
 308        * Class-D amplifier.  Keep the display reminder and add a short tone
 309        * so the MVP's active reminder is audible when the speaker is fitted. */
 310       memset(&action, 0, sizeof(action));
 311       action.type = VELAWEAR_ACTION_VIBRATE;
 312       action.priority = VELAWEAR_PRIORITY_NORMAL;
 313       action.params.vibrate.duration_ms = 800;
 314       action.params.vibrate.pattern = 0;
 315       if (action_manager_execute(engine->actions, &action) < 0)
 316         {
 317           syslog(LOG_WARNING,
 318                  "[Decision] Speaker reminder queue failed\n");
 319         }
 320 
 321       memset(&action, 0, sizeof(action));
 322       action.type = VELAWEAR_ACTION_CALL_LLM;
 323       action.priority = VELAWEAR_PRIORITY_NORMAL;
 324       snprintf(action.params.llm.prompt, sizeof(action.params.llm.prompt),
 325                "检测到用户持续静止，请给出一句简短的活动建议");
 326       if (action_manager_execute(engine->actions, &action) < 0)
 327         {
 328           syslog(LOG_WARNING,
 329                  "[Decision] Cloud LLM reminder queue failed\n");
 330         }
 331 
 332       /* Feed the normal event path once so the BLE Agent receives a
 333        * sedentary event as well as the local UI/audio reminder. */
 334       if (engine->events != NULL)
 335         {
 336           velawear_event_t timer_event;
 337 
 338           memset(&timer_event, 0, sizeof(timer_event));
 339           timer_event.type = VELAWEAR_EVENT_TIMER;
 340           timer_event.priority = VELAWEAR_PRIORITY_NORMAL;
 341           timer_event.timestamp = now;
 342           timer_event.data.timer.id = 1;
 343           if (event_manager_push(engine->events, &timer_event) < 0)
 344             {
 345               syslog(LOG_WARNING,
 346                      "[Decision] Sedentary event queue failed\n");
 347             }
 348         }
 349 
 350       syslog(LOG_INFO,
 351              "[Decision] Sedentary reminder queued after %lu s\n",
 352              (unsigned long)sedentary_threshold_sec(engine));
 353     }
 354 
 355   return ret;
 356 }
