 760       syslog(LOG_ERR, "[VelaWear] Config init failed: %d\n", ret);
 761       return ret;
 762     }
 763 
 764   /* Initialize event manager */
 765 
 766   ret = event_manager_init(&agent->events, agent->config.event_queue_size);
 767   if (ret < 0)
 768     {
 769       syslog(LOG_ERR, "[VelaWear] Event manager init failed: %d\n", ret);
 770       return ret;
 771     }
 772 
 773   /* Initialize state manager */
 774 
 775   ret = state_manager_init(&agent->state_mgr);
 776   if (ret < 0)
 777     {
 778       syslog(LOG_ERR, "[VelaWear] State manager init failed: %d\n", ret);
 779       return ret;
 780     }
 781   agent->state = state_manager_get_state(&agent->state_mgr);
 782 
 783   /* Initialize the LCD/LVGL status page on the main thread.  LVGL keeps
 784    * context in task-local storage, so timer handling stays in this thread. */
 785 #ifndef VELAWEAR_ENABLE_DISPLAY
 786 #define VELAWEAR_ENABLE_DISPLAY 1
 787 #endif
 788 #if VELAWEAR_ENABLE_DISPLAY
 789   ret = display_manager_init(&agent->display, &agent->state_mgr,
 790                              &agent->events);
 791   if (ret < 0)
 792     {
 793       syslog(LOG_WARNING, "[VelaWear] Display init failed: %d\n", ret);
 794       /* Non-fatal: the agent remains usable without a display. */
 795     }
 796 #else
 797   ret = -ENOTSUP;
 798   syslog(LOG_INFO, "[Display] disabled for BLE isolation\n");
 799 #endif
 800 
 801   /*
 802    * Core MVP mode keeps BLE optional so a controller/HCI fault cannot block
 803    * the IMU -> Agent -> LCD reminder loop. Re-enable with
 804    * -DVELAWEAR_ENABLE_BLE=1 after the HCI path is verified.
 805    */
 806 #ifndef VELAWEAR_ENABLE_BLE
 807 #define VELAWEAR_ENABLE_BLE 0
 808 #endif
 809 #if VELAWEAR_ENABLE_BLE
 810   ret = velawear_ble_init(&agent->config, &agent->events);
 811   if (ret < 0)
 812     {
 813       syslog(LOG_WARNING, "[VelaWear] BLE init failed: %d\n", ret);
 814     }
 815   else
 816     {
 817       agent->ble_available = true;
 818     }
 819   syslog(LOG_INFO, "[BLE] init result=%d available=%d\n", ret,
 820          agent->ble_available ? 1 : 0);
 821 #else
 822   ret = -ENOTSUP;
 823   syslog(LOG_INFO, "[BLE] deferred; core MVP mode\n");
 824 #endif
 825 
 826   velawear_buttons_open();
 827 
 828   /* Initialize decision engine */
 829 
 830   ret = decision_engine_init(&agent->engine, &agent->config);
 831   if (ret < 0)
 832     {
 833       syslog(LOG_ERR, "[VelaWear] Decision engine init failed: %d\n", ret);
 834       return ret;
 835     }
 836 
 837   /* Initialize action manager */
 838 
 839   ret = action_manager_init(&agent->actions);
 840   if (ret < 0)
 841     {
 842       syslog(LOG_ERR, "[VelaWear] Action manager init failed: %d\n", ret);
 843       return ret;
 844     }
 845 
 846   ret = decision_engine_set_action_manager(&agent->engine,
 847                                              &agent->actions);
 848   if (ret < 0)
 849     {
 850       syslog(LOG_ERR, "[VelaWear] Decision action routing setup failed: %d\n",
 851              ret);
 852       return ret;
 853     }
 854 
 855   ret = decision_engine_set_state_manager(&agent->engine,
 856                                           &agent->state_mgr);
 857   if (ret < 0)
 858     {
 859       syslog(LOG_ERR, "[VelaWear] Decision state routing setup failed: %d\n",
 860              ret);
 861       return ret;
 862     }
 863 
 864   ret = decision_engine_set_event_manager(&agent->engine,
 865                                           &agent->events);
 866   if (ret < 0)
 867     {
 868       syslog(LOG_ERR, "[VelaWear] Decision event routing setup failed: %d\n",
 869              ret);
 870       return ret;
 871     }
 872 
 873   /* Initialize sensor drivers */
 874 
 875   ret = velawear_retry_imu(agent);
 876   if (ret < 0)
 877     {
 878       syslog(LOG_WARNING, "[VelaWear] IMU sensor init failed after retry: %d\n",
 879              ret);
 880       velawear_set_degradation_mode(agent, VELAWEAR_MODE_INDEPENDENT,
 881                                      "imu unavailable");
 882     }
 883 
 884   ret = velawear_retry_audio(agent);
 885   if (ret < 0)
 886     {
 887       syslog(LOG_WARNING,
 888              "[VelaWear] Audio sensor init failed after retry: %d\n", ret);
 889       syslog(LOG_WARNING,
 890              "[Degrade] Microphone input unavailable; display/speaker actions remain\n");
 891     }
 892 
 893   /* Initialize LLM client */
 894 
 895   ret = velawear_llm_init(&agent->llm);
 896   if (ret < 0)
 897     {
 898       syslog(LOG_WARNING, "[VelaWear] LLM init failed: %d\n", ret);
 899       velawear_set_degradation_mode(agent, VELAWEAR_MODE_INDEPENDENT,
 900                                      "llm unavailable");

