   195	int audio_sensor_init(velawear_audio_t *audio)
   196	{
   197	  int ret;
   198	
   199	  if (audio == NULL)
   200	    {
   201	      return VELAWEAR_ERR_INVAL;
   202	    }
   203	
   204	  memset(audio, 0, sizeof(velawear_audio_t));
   205	  audio->fd = -1;
   206	  audio->sample_rate = 16000;
   207	
   208	  syslog(LOG_INFO,
   209	         "[Audio] Probing onboard MEMS microphone via direct AUDCODEC ADC\n");
   210	  ret = velawear_mic_hw_test();
   211	  if (ret != 0)
   212	    {
   213	      syslog(LOG_WARNING,
   214	             "[Audio] Onboard MEMS microphone ADC probe failed: %d\n", ret);
   215	      return VELAWEAR_ERR_IO;
   216	    }
   217	
   218	  audio->initialized = true;
   219	  syslog(LOG_INFO,
   220	         "[Audio] Onboard MEMS microphone ready via direct AUDCODEC ADC at %d Hz\n",
   221	         audio->sample_rate);
   222	  return VELAWEAR_OK;
   223	}
   224	
   225	int audio_sensor_start(velawear_audio_t *audio, void *events)
   226	{
   227	  int ret;
   228	
   229	  if (audio == NULL || !audio->initialized)
   230	    {
   231	      return VELAWEAR_ERR_IO;
   232	    }
   233	  if (audio->thread_started || audio->stream_running)
   234	    {
   235	      return VELAWEAR_ERR_BUSY;
   236	    }
   237	
   238	  ret = velawear_mic_stream_start();
   239	  if (ret < 0)
   240	    {
   241	      return VELAWEAR_ERR_IO;
   242	    }
   243	
   244	  audio->events = events;
   245	  audio->level_active = false;
   246	  audio->latest_avg_abs = 0;
   247	  audio->latest_peak_abs = 0;
   248	  audio->stream_running = true;
   249	  ret = pthread_create(&audio->thread, NULL, audio_sensor_thread, audio);
   250	  if (ret != 0)
   251	    {
   252	      audio->stream_running = false;
   253	      velawear_mic_stream_stop();
   254	      syslog(LOG_ERR, "[AudioStream] level worker start failed: %d\n", ret);
   255	      return VELAWEAR_ERR_IO;
   256	    }
   257	
   258	  audio->thread_started = true;
   259	  return VELAWEAR_OK;
   260	}
   261	
   262	void audio_sensor_cleanup(velawear_audio_t *audio)
   263	{
   264	  if (audio == NULL)
   265	    {
   266	      return;
   267	    }
   268	
   269	  audio->stream_running = false;
   270	  if (audio->thread_started)
   271	    {
   272	      pthread_join(audio->thread, NULL);
   273	      audio->thread_started = false;
   274	    }
   275	
   276	  velawear_mic_stream_stop();
   277	  if (audio->fd >= 0)
   278	    {
   279	      close(audio->fd);
   280	      audio->fd = -1;
   281	    }
   282	
   283	  audio->events = NULL;
   284	  audio->initialized = false;
   285	  syslog(LOG_INFO, "[Audio] Cleaned up\n");
   286	}

