/*
 * VelaWear Agent - BLE service
 *
 * Service contract:
 *   status     READ + NOTIFY: [motion_type, intensity_percent, alert]
 *   threshold  READ + WRITE:  uint16 little-endian seconds
 */

#include <nuttx/config.h>

