def _bounded_utf8(text: str, maximum: int = LLM_TEXT_MAX) -> bytes:
    encoded = text.encode("utf-8", errors="replace")
    if len(encoded) <= maximum:
        return encoded
    return encoded[:maximum].decode("utf-8", errors="ignore").encode("utf-8")


def _bounded_pcm(pcm: bytes, maximum_bytes: int) -> bytes:
    """Keep PCM within the board buffer and never cut one sample in half."""
    maximum_bytes = max(2, maximum_bytes) & ~1
    pcm = pcm[:maximum_bytes]
    return pcm if len(pcm) % 2 == 0 else pcm[:-1]


def resample_pcm_s16le(pcm: bytes, input_rate: int, output_rate: int) -> bytes:
    """Resample mono signed-16-bit little-endian PCM with linear interpolation."""
    if input_rate <= 0 or output_rate <= 0:
        raise ValueError("sample rate must be positive")
    if len(pcm) % 2 != 0:
        raise ValueError("PCM payload must contain complete 16-bit samples")
    if input_rate == output_rate:
        return pcm

    sample_count = len(pcm) // 2
    if sample_count < 2:
        return pcm

    samples = struct.unpack(f"<{sample_count}h", pcm)
    output_count = max(1, (sample_count * output_rate) // input_rate)
    output = bytearray(output_count * 2)
    for output_index in range(output_count):
        source_position = output_index * input_rate / output_rate
        left_index = min(int(source_position), sample_count - 1)
        right_index = min(left_index + 1, sample_count - 1)
        fraction = source_position - left_index
        value = round(
            samples[left_index]
            + (samples[right_index] - samples[left_index]) * fraction
        )
        value = max(-32768, min(32767, value))
        struct.pack_into("<h", output, output_index * 2, value)
    return bytes(output)


def encode_llm_response(sequence: int, status: int, text: str = "") -> bytes:
    if not 0 <= sequence <= 0xFFFF:
        raise ValueError("sequence out of range")
    if status not in (LLM_STATUS_OK, LLM_STATUS_ERROR):
        raise ValueError("invalid LLM status")
    payload = _bounded_utf8(text)
    return bytes(
        (
            PROTOCOL_VERSION,
            LLM_RESPONSE_TYPE,
            sequence & 0xFF,
            (sequence >> 8) & 0xFF,
            status,
            len(payload) & 0xFF,
            (len(payload) >> 8) & 0xFF,
        )
    ) + payload


