class BridgeError(RuntimeError):
    """Expected bridge or cloud failure that should trigger board fallback."""


@dataclass(frozen=True)
class BridgeConfig:
    address: str
    api_key: str
    base_url: str
    model: str
    http_timeout: float
    connect_timeout: float
    system_prompt: str
    trigger_sequence: int = 1
    tts_enabled: bool = False
    tts_base_url: str = DEFAULT_TTS_BASE_URL
    tts_api_key: str = ""
    tts_model: str = DEFAULT_TTS_MODEL
    tts_voice: str = DEFAULT_TTS_VOICE
    tts_speed: float = 1.0
    tts_input_rate: int = DEFAULT_TTS_INPUT_RATE
    tts_timeout: float = 20.0
    tts_max_seconds: float = AUDIO_MAX_SECONDS
    tts_instructions: str = (
