    )
    memory_turns: int = 6


def load_config(environ: Optional[dict[str, str]] = None) -> BridgeConfig:
    env = os.environ if environ is None else environ
    api_key = env.get("VELAWEAR_LLM_API_KEY", "") or env.get("OPENAI_API_KEY", "")

    def env_bool(name: str, default: bool) -> bool:
        value = env.get(name)
        if value is None:
            return default
        return value.strip().lower() not in {"", "0", "false", "no", "off"}

    try:
        memory_turns = max(0, min(12, int(env.get("VELAWEAR_MEMORY_TURNS", "6"))))
    except ValueError:
        memory_turns = 6

    try:
        tts_speed = max(0.5, min(2.0, float(env.get("VELAWEAR_TTS_SPEED", "1.0"))))
    except ValueError:
        tts_speed = 1.0

    try:
        tts_max_seconds = max(
            0.25,
            min(AUDIO_MAX_SECONDS, float(env.get("VELAWEAR_TTS_MAX_SECONDS", "2.0"))),
        )
    except ValueError:
        tts_max_seconds = AUDIO_MAX_SECONDS

    try:
        tts_input_rate = int(
            env.get("VELAWEAR_TTS_INPUT_RATE", str(DEFAULT_TTS_INPUT_RATE))
        )
    except ValueError:
        tts_input_rate = DEFAULT_TTS_INPUT_RATE

    return BridgeConfig(
        address=env.get("VELAWEAR_BLE_ADDRESS", DEFAULT_ADDRESS),
        api_key=api_key,
        base_url=env.get("VELAWEAR_LLM_BASE_URL", DEFAULT_BASE_URL),
