        tts_api_key=env.get("VELAWEAR_TTS_API_KEY", "") or api_key,
        tts_model=env.get("VELAWEAR_TTS_MODEL", DEFAULT_TTS_MODEL),
        tts_voice=env.get("VELAWEAR_TTS_VOICE", DEFAULT_TTS_VOICE),
        tts_speed=tts_speed,
        tts_input_rate=tts_input_rate,
        tts_timeout=float(env.get("VELAWEAR_TTS_HTTP_TIMEOUT", "20")),
        tts_max_seconds=tts_max_seconds,
        tts_instructions=env.get(
            "VELAWEAR_TTS_INSTRUCTIONS",
            "用自然、温柔、亲近的年轻女性语气说话，像一位体贴的 AI 女友。"
            "不要夸张，不要播音腔，中文发音清晰。",
        ),
        memory_turns=memory_turns,
    )


def _bounded_utf8(text: str, maximum: int = LLM_TEXT_MAX) -> bytes:
    encoded = text.encode("utf-8", errors="replace")
    if len(encoded) <= maximum:
        return encoded
    return encoded[:maximum].decode("utf-8", errors="ignore").encode("utf-8")


def _bounded_pcm(pcm: bytes, maximum_bytes: int) -> bytes:
    """Keep PCM within the board buffer and never cut one sample in half."""
    maximum_bytes = max(2, maximum_bytes) & ~1
    pcm = pcm[:maximum_bytes]
    return pcm if len(pcm) % 2 == 0 else pcm[:-1]


def resample_pcm_s16le(pcm: bytes, input_rate: int, output_rate: int) -> bytes:
    """Resample mono signed-16-bit little-endian PCM with linear interpolation."""
    if input_rate <= 0 or output_rate <= 0:
        raise ValueError("sample rate must be positive")
    if len(pcm) % 2 != 0:
        raise ValueError("PCM payload must contain complete 16-bit samples")
    if input_rate == output_rate:
        return pcm

    sample_count = len(pcm) // 2
    if sample_count < 2:
        return pcm

    samples = struct.unpack(f"<{sample_count}h", pcm)
    output_count = max(1, (sample_count * output_rate) // input_rate)
    output = bytearray(output_count * 2)
    for output_index in range(output_count):
        source_position = output_index * input_rate / output_rate
        left_index = min(int(source_position), sample_count - 1)
        right_index = min(left_index + 1, sample_count - 1)
        fraction = source_position - left_index
        value = round(
            samples[left_index]
            + (samples[right_index] - samples[left_index]) * fraction
        )
        value = max(-32768, min(32767, value))
        struct.pack_into("<h", output, output_index * 2, value)
    return bytes(output)


def encode_llm_response(sequence: int, status: int, text: str = "") -> bytes:
    if not 0 <= sequence <= 0xFFFF:
        raise ValueError("sequence out of range")
    if status not in (LLM_STATUS_OK, LLM_STATUS_ERROR):
        raise ValueError("invalid LLM status")
    payload = _bounded_utf8(text)
    return bytes(
        (
            PROTOCOL_VERSION,
            LLM_RESPONSE_TYPE,
            sequence & 0xFF,
            (sequence >> 8) & 0xFF,
            status,
            len(payload) & 0xFF,
            (len(payload) >> 8) & 0xFF,
        )
    ) + payload


def encode_agent_command(sequence: int, command_id: int, argument: int = 0) -> bytes:
    if not 0 <= sequence <= 0xFFFF:
        raise ValueError("sequence out of range")
    if not 0 <= command_id <= 0xFF:
        raise ValueError("command id out of range")
    if not 0 <= argument <= 0xFFFF:
        raise ValueError("argument out of range")
    return bytes(
        (
            PROTOCOL_VERSION,
            command_id,
            sequence & 0xFF,
            sequence & 0xFF,
            (sequence >> 8) & 0xFF,
            argument & 0xFF,
            (argument >> 8) & 0xFF,
        )
    )


def encode_chat_input(text: str) -> bytes:
    payload = _bounded_utf8(text, LLM_TEXT_MAX)
    if not payload:
        raise ValueError("chat input must not be empty")
    return payload


def decode_llm_request(frame: bytes) -> Tuple[int, str]:
    if len(frame) < LLM_REQUEST_HEADER_SIZE:
        raise BridgeError("short LLM request")
    if frame[0] != PROTOCOL_VERSION or frame[1] != LLM_REQUEST_TYPE:
        raise BridgeError("invalid LLM request header")
    sequence = frame[2] | (frame[3] << 8)
    length = frame[4] | (frame[5] << 8)
    if length > LLM_TEXT_MAX or len(frame) != LLM_REQUEST_HEADER_SIZE + length:
        raise BridgeError("invalid LLM request length")
    try:
        prompt = frame[LLM_REQUEST_HEADER_SIZE:].decode("utf-8")
    except UnicodeDecodeError as exc:
        raise BridgeError("invalid UTF-8 prompt") from exc
    if not prompt:
        raise BridgeError("empty LLM prompt")
    return sequence, prompt


def _extract_text(payload: Any) -> str:
    choices = payload.get("choices")
    if not isinstance(choices, list) or not choices:
        raise BridgeError("cloud response has no choices")
    message = choices[0].get("message")
    if not isinstance(message, dict):
        raise BridgeError("cloud response has no message")
    content = message.get("content")
    if isinstance(content, str):
        result = content.strip()
    elif isinstance(content, list):
        parts = []
        for item in content:
            if isinstance(item, dict) and isinstance(item.get("text"), str):
                parts.append(item["text"])
        result = "".join(parts).strip()
    else:
        result = ""
    if not result:
        raise BridgeError("cloud response has empty content")
    return result


def build_cloud_request(
    config: BridgeConfig,
    prompt: str,
    history: Optional[list[dict[str, str]]] = None,
) -> bytes:
    if not config.api_key:
        raise BridgeError("VELAWEAR_LLM_API_KEY or OPENAI_API_KEY is not set")
    if not config.base_url or not config.model:
        raise BridgeError("cloud endpoint or model is not configured")
    messages: list[dict[str, str]] = [
        {"role": "system", "content": config.system_prompt}
    ]
    if history:
        messages.extend(
            item
            for item in history[-(config.memory_turns * 2) :]
            if item.get("role") in {"user", "assistant"}
            and isinstance(item.get("content"), str)
        )
    messages.append({"role": "user", "content": prompt})
    body = {
        "model": config.model,
        "messages": messages,
        "temperature": 0.2,
    }
    return json.dumps(body, ensure_ascii=False).encode("utf-8")


def call_cloud(
    config: BridgeConfig,
    prompt: str,
    history: Optional[list[dict[str, str]]] = None,
) -> str:
    request = urllib.request.Request(
        config.base_url,
        data=build_cloud_request(config, prompt, history),
        headers={
            "Authorization": f"Bearer {config.api_key}",
            "Content-Type": "application/json",
            "Accept": "application/json",
        },
        method="POST",
    )
    try:
        with urllib.request.urlopen(
            request,
            timeout=config.http_timeout,
            context=ssl.create_default_context(),
        ) as stream:
            if stream.status < 200 or stream.status >= 300:
                raise BridgeError(f"cloud HTTP status {stream.status}")
            raw = stream.read(1024 * 1024)
    except urllib.error.HTTPError as exc:
        raise BridgeError(f"cloud HTTP status {exc.code}") from exc
    except (urllib.error.URLError, TimeoutError, OSError) as exc:
        raise BridgeError(f"cloud transport {type(exc).__name__}") from exc

    try:
        payload = json.loads(raw.decode("utf-8"))
    except (UnicodeDecodeError, json.JSONDecodeError) as exc:
        raise BridgeError("cloud response is not JSON") from exc
    return _extract_text(payload)


def build_tts_request(config: BridgeConfig, text: str) -> bytes:
    if not config.tts_api_key:
        raise BridgeError("VELAWEAR_TTS_API_KEY or LLM API key is not set")
    if not config.tts_base_url or not config.tts_model or not config.tts_voice:
        raise BridgeError("TTS endpoint, model, or voice is not configured")

    body: dict[str, Any] = {
        "model": config.tts_model,
        "input": text,
        "voice": config.tts_voice,
        "response_format": "pcm",
        "speed": config.tts_speed,
    }
    if config.tts_instructions:
        body["instructions"] = select_tts_instructions(
            config.tts_instructions, text
        )
    return json.dumps(body, ensure_ascii=False).encode("utf-8")


def select_tts_instructions(base: str, text: str) -> str:
    """Add restrained prosody guidance from the companion's current intent."""
    if any(word in text for word in ("难过", "委屈", "孤单", "辛苦", "累", "休息")):
        mood = "这句话是在安慰和陪伴，语气更柔和、放慢一点，带有真诚关心。"
    elif any(word in text for word in ("加油", "棒", "成功", "开心", "太好了")):
        mood = "这句话是在鼓励和庆祝，语气明亮、有温度，但不要夸张。"
    elif any(word in text for word in ("想你", "陪你", "我在", "早安", "晚安")):
        mood = "这句话是在亲近地陪伴，语气自然、轻柔，像熟悉的人在身边说话。"
