async def run_bridge(
    config: BridgeConfig,
    once: bool,
    trigger_reminder: bool = False,
    chat_prompt: Optional[str] = None,
) -> int:
    logger = logging.getLogger("velawear-llm-bridge")
    while True:
        try:
            await serve_once(config, logger, trigger_reminder, chat_prompt)
            if once:
                return 0
        except (BridgeError, asyncio.CancelledError) as exc:
            if isinstance(exc, asyncio.CancelledError):
                raise
            logger.error("bridge_cycle_failed reason=%s", str(exc))
            if once:
                return 1
            await asyncio.sleep(2)
        except Exception as exc:
            logger.error(
                "bridge_cycle_failed type=%s reason=%s",
                type(exc).__name__,
                str(exc),
            )
            if once:
                return 1
            await asyncio.sleep(2)


def parse_args(argv: Optional[list[str]] = None) -> argparse.Namespace:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument(
        "--once",
        action="store_true",
        help="exit after one bridge cycle or the first bridge failure",
    )
    parser.add_argument(
        "--verbose",
        action="store_true",
        help="enable debug logging without printing credentials or prompt text",
    )
    parser.add_argument(
        "--trigger-reminder",
        action="store_true",
        help="HIL-only: trigger a SHOW_REMINDER command after BLE setup",
    )
    parser.add_argument(
        "--prompt",
        dest="chat_prompt",
        help="send one UTF-8 chat message through CHAT_INPUT after BLE setup",
    )
    return parser.parse_args(argv)


def main(argv: Optional[list[str]] = None) -> int:
    args = parse_args(argv)
    logging.basicConfig(
        level=logging.DEBUG if args.verbose else logging.INFO,
        format="%(asctime)s %(levelname)s %(message)s",
    )
    config = load_config()
    if not config.api_key:
        logging.getLogger("velawear-llm-bridge").warning(
            "cloud key is not configured; board will use local fallback"
        )
    try:
        return asyncio.run(
            run_bridge(
                config,
                args.once,
                args.trigger_reminder,
                args.chat_prompt,
            )
        )
    except KeyboardInterrupt:
        return 130


if __name__ == "__main__":
    sys.exit(main())

