def call_cloud(
    config: BridgeConfig,
    prompt: str,
    history: Optional[list[dict[str, str]]] = None,
) -> str:
    request = urllib.request.Request(
        config.base_url,
        data=build_cloud_request(config, prompt, history),
        headers={
            "Authorization": f"Bearer {config.api_key}",
            "Content-Type": "application/json",
            "Accept": "application/json",
        },
        method="POST",
    )
    try:
        with urllib.request.urlopen(
            request,
            timeout=config.http_timeout,
            context=ssl.create_default_context(),
        ) as stream:
            if stream.status < 200 or stream.status >= 300:
                raise BridgeError(f"cloud HTTP status {stream.status}")
            raw = stream.read(1024 * 1024)
    except urllib.error.HTTPError as exc:
        raise BridgeError(f"cloud HTTP status {exc.code}") from exc
    except (urllib.error.URLError, TimeoutError, OSError) as exc:
        raise BridgeError(f"cloud transport {type(exc).__name__}") from exc

    try:
        payload = json.loads(raw.decode("utf-8"))
    except (UnicodeDecodeError, json.JSONDecodeError) as exc:
        raise BridgeError("cloud response is not JSON") from exc
    return _extract_text(payload)


def build_tts_request(config: BridgeConfig, text: str) -> bytes:
    if not config.tts_api_key:
        raise BridgeError("VELAWEAR_TTS_API_KEY or LLM API key is not set")
    if not config.tts_base_url or not config.tts_model or not config.tts_voice:
        raise BridgeError("TTS endpoint, model, or voice is not configured")

    body: dict[str, Any] = {
        "model": config.tts_model,
        "input": text,
        "voice": config.tts_voice,
        "response_format": "pcm",
        "speed": config.tts_speed,
    }
    if config.tts_instructions:
        body["instructions"] = select_tts_instructions(
            config.tts_instructions, text
        )
    return json.dumps(body, ensure_ascii=False).encode("utf-8")


def select_tts_instructions(base: str, text: str) -> str:
    """Add restrained prosody guidance from the companion's current intent."""
    if any(word in text for word in ("难过", "委屈", "孤单", "辛苦", "累", "休息")):
        mood = "这句话是在安慰和陪伴，语气更柔和、放慢一点，带有真诚关心。"
    elif any(word in text for word in ("加油", "棒", "成功", "开心", "太好了")):
        mood = "这句话是在鼓励和庆祝，语气明亮、有温度，但不要夸张。"
    elif any(word in text for word in ("想你", "陪你", "我在", "早安", "晚安")):
        mood = "这句话是在亲近地陪伴，语气自然、轻柔，像熟悉的人在身边说话。"
    elif any(word in text for word in ("提醒", "活动", "喝水", "补充水分")):
        mood = "这句话是温柔提醒，语气清楚、关心，不要像警报或播音。"
    else:
        mood = "保持自然交流感，适度使用停顿和语气变化，不要平直朗读。"
    return f"{base} {mood}"


def call_tts(config: BridgeConfig, text: str) -> bytes:
    request = urllib.request.Request(
        config.tts_base_url,
        data=build_tts_request(config, text),
        headers={
            "Authorization": f"Bearer {config.tts_api_key}",
            "Content-Type": "application/json",
            "Accept": "audio/pcm",
        },
        method="POST",
    )
    try:
        with urllib.request.urlopen(
            request,
            timeout=config.tts_timeout,
            context=ssl.create_default_context(),
        ) as stream:
            if stream.status < 200 or stream.status >= 300:
                raise BridgeError(f"TTS HTTP status {stream.status}")
            raw = stream.read(1024 * 1024)
    except urllib.error.HTTPError as exc:
        raise BridgeError(f"TTS HTTP status {exc.code}") from exc
    except (urllib.error.URLError, TimeoutError, OSError) as exc:
        raise BridgeError(f"TTS transport {type(exc).__name__}") from exc

    if not raw:
        raise BridgeError("TTS response is empty")
    if len(raw) % 2 != 0:
        raw = raw[:-1]
    if not raw:
        raise BridgeError("TTS response has no complete PCM sample")
    return raw


def prepare_voice_pcm(config: BridgeConfig, pcm: bytes) -> bytes:
    maximum_bytes = int(AUDIO_SAMPLE_RATE * config.tts_max_seconds * 2)
    pcm = resample_pcm_s16le(pcm, config.tts_input_rate, AUDIO_SAMPLE_RATE)
    pcm = _bounded_pcm(pcm, min(AUDIO_MAX_BYTES, maximum_bytes))
    if not pcm:
        raise BridgeError("TTS PCM is empty after resampling")
    return pcm


def encode_audio_start(stream_id: int, pcm: bytes) -> bytes:
    if not 0 <= stream_id <= 0xFFFF:
        raise ValueError("audio stream id out of range")
    if len(pcm) == 0 or len(pcm) > AUDIO_MAX_BYTES or len(pcm) % 2 != 0:
        raise ValueError("audio PCM length is outside the board limits")
    return struct.pack(
        "<BBHHBBIII",
        PROTOCOL_VERSION,
        AUDIO_START_TYPE,
        stream_id,
        AUDIO_SAMPLE_RATE,
        AUDIO_CHANNELS,
        AUDIO_BITS_PER_SAMPLE,
        len(pcm) // 2,
        len(pcm),
        zlib.crc32(pcm) & 0xFFFFFFFF,
    )


def encode_audio_data(stream_id: int, offset: int, payload: bytes) -> bytes:
    if not 0 <= stream_id <= 0xFFFF or offset < 0 or offset > 0xFFFFFFFF:
        raise ValueError("audio data header out of range")
    if not payload or len(payload) % 2 != 0:
        raise ValueError("audio data must contain complete samples")
    return struct.pack(
        "<BBHI", PROTOCOL_VERSION, AUDIO_DATA_TYPE, stream_id, offset
    ) + payload


def encode_audio_end(stream_id: int, pcm: bytes) -> bytes:
    if not 0 <= stream_id <= 0xFFFF:
        raise ValueError("audio stream id out of range")
    return struct.pack(
        "<BBHII",
        PROTOCOL_VERSION,
        AUDIO_END_TYPE,
        stream_id,
        len(pcm),
        zlib.crc32(pcm) & 0xFFFFFFFF,
    )


async def send_audio_stream(
    client: Any, stream_id: int, pcm: bytes, logger: logging.Logger
) -> None:
    mtu = int(getattr(client, "mtu_size", 23) or 23)
    payload_size = max(2, mtu - 3 - AUDIO_DATA_HEADER_SIZE)
    payload_size = min(240, payload_size) & ~1
    if payload_size < 2:
        raise BridgeError(f"BLE MTU too small for audio: {mtu}")

    await client.write_gatt_char(
        AUDIO_STREAM_UUID, encode_audio_start(stream_id, pcm), response=True
    )
    for offset in range(0, len(pcm), payload_size):
        payload = pcm[offset : offset + payload_size]
        await client.write_gatt_char(
            AUDIO_STREAM_UUID,
            encode_audio_data(stream_id, offset, payload),
            response=True,
        )
    await client.write_gatt_char(
        AUDIO_STREAM_UUID, encode_audio_end(stream_id, pcm), response=True
    )
    logger.info(
        "tts_audio_sent stream_id=%d bytes=%d samples=%d mtu=%d chunk=%d",
        stream_id,
        len(pcm),
        len(pcm) // 2,
        mtu,
        payload_size,
    )


async def _find_device(
    scanner: Any, address: str, name: str, timeout: float
) -> Any:
    try:
        devices = await scanner.discover(timeout=timeout, return_adv=True)
    except TypeError:
        devices = await scanner.discover(timeout=timeout)

    if isinstance(devices, dict):
        entries = list(devices.values())
    else:
        entries = [(device, None) for device in devices]

    wanted_address = address.strip().casefold()
    wanted_name = name.strip().casefold()
    wanted_service = SERVICE_UUID.casefold()
    for entry in entries:
        if isinstance(entry, tuple) and len(entry) == 2:
            device, advertisement = entry
        else:
            device, advertisement = entry, None

        device_address = str(getattr(device, "address", ""))
        advertised_names = {
            value.casefold()
            for value in (
                getattr(device, "name", None),
                getattr(advertisement, "local_name", None),
            )
            if isinstance(value, str) and value
        }
        service_uuids = {
            str(value).casefold()
            for value in (getattr(advertisement, "service_uuids", None) or [])
        }
        if (
            wanted_address and device_address.casefold() == wanted_address
        ) or (wanted_name and wanted_name in advertised_names) or (
            wanted_service in service_uuids
        ):
            return device
    return None


async def serve_once(
    config: BridgeConfig,
    logger: logging.Logger,
    trigger_reminder: bool = False,
    chat_prompt: Optional[str] = None,
) -> None:
    stage = "import_bleak"
    try:
        from bleak import BleakClient, BleakScanner
    except ImportError as exc:
        raise BridgeError("Bleak is required: python -m pip install bleak") from exc

    try:
        stage = "scan"
        device = await _find_device(
            BleakScanner,
            config.address,
            config.device_name,
            config.connect_timeout,
        )
        if device is None:
            raise BridgeError(
                "BLE device not found: address=%s name=%s service=%s"
                % (config.address, config.device_name, SERVICE_UUID)
            )
        logger.info(
            "device_found=true address=%s name=%s",
            getattr(device, "address", ""),
            config.device_name,
        )

        queue: asyncio.Queue[bytes] = asyncio.Queue(maxsize=1)
        history: list[dict[str, str]] = []

        def on_request(_: Any, data: bytearray) -> None:
            try:
                queue.put_nowait(bytes(data))
            except asyncio.QueueFull:
                logger.warning("LLM request dropped: bridge is busy")

        stage = "connect"
        async with BleakClient(device, timeout=config.connect_timeout) as client:
            stage = "subscribe_llm_request"
            await client.start_notify(LLM_REQUEST_UUID, on_request)
            logger.info("connected=true llm_bridge_ready=true")
            if trigger_reminder:
                stage = "trigger_reminder"
                command = encode_agent_command(
                    config.trigger_sequence, AGENT_SHOW_REMINDER, argument=2
                )
                await client.write_gatt_char(
                    AGENT_COMMAND_UUID, command, response=True
                )
                logger.info(
                    "trigger_reminder=true command_seq=%d", config.trigger_sequence
                )
            if chat_prompt is not None:
                stage = "chat_input"
                chat_frame = encode_chat_input(chat_prompt)
                await client.write_gatt_char(
                    CHAT_INPUT_UUID, chat_frame, response=True
                )
