  ret = bt_conn_cb_register(&velawear_conn_callbacks);
  if (ret < 0)
    {
      pthread_mutex_destroy(&g_lock);
      g_config = NULL;
      g_events = NULL;
      syslog(LOG_WARNING, "[BLE] Connection callback registration failed: %d\n",
