  frame[2] = (uint8_t)(sequence & 0xff);
  frame[3] = (uint8_t)(sequence >> 8);
  g_llm_pending_sequence = sequence;
  g_llm_response_status = VELAWEAR_AGENT_LLM_STATUS_ERROR;
  g_llm_response_length = 0;
  g_llm_response_text[0] = '\0';
  g_llm_waiting = true;
