                                   size_t length)
{
  size_t i;

  for (i = 0; i < length; i++)
    {
      uint32_t bit;

      crc ^= data[i];
      for (bit = 0; bit < 8; bit++)
        {
          crc = (crc & 1U) != 0U ?
                (crc >> 1) ^ 0xedb88320U : crc >> 1;
        }
    }

  return crc;
}

