    }
  else
    {
      syslog(LOG_INFO, "[BLE] Advertising active after disconnect\n");
    }
}

static void velawear_ble_disconnected(struct bt_conn *conn, uint8_t reason)
{
  struct bt_conn *notify_conn;
  int ret;

  (void)conn;
  pthread_mutex_lock(&g_lock);
  notify_conn = g_status_notify_conn;
  g_status_notify_conn = NULL;
  g_status_notify_enabled = false;
  pthread_mutex_unlock(&g_lock);

  if (notify_conn != NULL)
    {
      bt_conn_unref(notify_conn);
    }

  ret = k_work_schedule(&g_adv_restart_work, K_MSEC(200));
  if (ret < 0)
    {
      syslog(LOG_WARNING,
             "[BLE] disconnected reason=0x%02x; restart schedule failed: %d\n",
             reason, ret);
    }
}

