static int sf32lb52_bt_send(struct bt_driver_s *drv,
                            enum bt_buf_type_e type,
                            void *data, size_t len)
{
  struct sf32lb52_bt_priv_s *priv = &g_sf32lb52_bt_priv;
  uint8_t *hdr = (uint8_t *)data - drv->head_reserve;
  uint16_t opcode;
  int ret;


  switch (type)
    {
      case BT_CMD:
        *hdr = H4_CMD;
        break;
      case BT_ACL_OUT:
        *hdr = H4_ACL;
        break;
      case BT_ISO_OUT:
        *hdr = H4_ISO;
        break;
      default:
        return -EINVAL;
    }

  if (type == BT_CMD && len >= sizeof(struct bt_hci_cmd_hdr_s))
    {
      opcode = sf32lb52_bt_get_le16(data);
#if SF32LB52_BT_TRACE
      syslog(LOG_INFO, "sf32lb52 bth4 tx cmd: opcode=%04x len=%lu\\n",
             opcode, (unsigned long)len);
#endif
#if SF32LB52_BT_CONN_TRACE
      if (opcode == 0x2022 || opcode == 0x2016 ||
          opcode == 0x2032 || opcode == 0x0c35)
        {
          syslog(LOG_WARNING,
                 "sf32lb52 bth4 conn cmd: opcode=%04x len=%lu\n",
                 opcode, (unsigned long)len);
        }
#endif
      if (sf32lb52_bt_emulate_cmd(priv, opcode, &ret))
        {
          return ret < 0 ? ret : len;
        }

      ret = sf32lb52_bt_ensure_controller_enabled(opcode);
      if (ret < 0)
        {
          return ret;
        }
    }
  else
    {
      ret = sf32lb52_bt_ensure_controller_enabled(0);
      if (ret < 0)
        {
          return ret;
        }
    }

  priv->drop_rx_until_tx = false;

#if SF32LB52_BT_FORCE_ACL_START
  if (type == BT_ACL_OUT && len >= 4)
    {
      uint16_t handle_flags = sf32lb52_bt_get_le16(&hdr[1]);

      /* SF32LB52 LCPU rejects the Zblue LE single-packet PB=0 form
       * with HCI Hardware Error.  Translate only the single-packet
       * start form to PB=2; continuation/complete flags are preserved.
       */
      if ((handle_flags & 0x3000) == 0)
        {
          sf32lb52_bt_put_le16(&hdr[1], handle_flags | 0x2000);
        }
    }
#endif

  if (SF32LB52_BT_TRACE && type == BT_ACL_OUT)
    {
      syslog(LOG_INFO,
             "sf32lb52 bth4 tx: type=%u len=%lu h4=%02x acl=%02x %02x %02x %02x\n",
             (unsigned int)type,
             (unsigned long)(len + drv->head_reserve),
             hdr[0],
             len >= 1 ? hdr[1] : 0,
             len >= 2 ? hdr[2] : 0,
             len >= 3 ? hdr[3] : 0,
             len >= 4 ? hdr[4] : 0);
    }

#if SF32LB52_BT_CONN_TRACE
  if (type == BT_ACL_OUT)
    {
      syslog(LOG_WARNING,
             "sf32lb52 bth4 tx acl: total=%lu handle=%02x%02x len=%02x%02x data=%02x%02x%02x%02x%02x%02x%02x\n",
             (unsigned long)(len + drv->head_reserve),
             len >= 1 ? hdr[1] : 0,
             len >= 2 ? hdr[2] : 0,
             len >= 3 ? hdr[3] : 0,
             len >= 4 ? hdr[4] : 0,
             len >= 5 ? hdr[5] : 0,
             len >= 6 ? hdr[6] : 0,
             len >= 7 ? hdr[7] : 0,
             len >= 8 ? hdr[8] : 0,
             len >= 9 ? hdr[9] : 0,
             len >= 10 ? hdr[10] : 0,
             len >= 11 ? hdr[11] : 0);
    }
#endif
  ret = sf32lb52_host_send_packet(hdr, len + drv->head_reserve);
  if (ret < 0)
    {
      return ret;
    }

  return len;
}

static int sf32lb52_bt_ensure_controller_enabled(uint16_t opcode)
{
  int ret;

  ret = sf32lb52_bt_controller_enable();
  if (ret < 0)
    {
      syslog(LOG_ERR,
             "sf32lb52 bth4 controller enable failed before opcode=0x%04x: %d\n",
             opcode,
             ret);
    }

  return ret;
}

static int sf32lb52_bt_open(struct bt_driver_s *drv)
{
  int ret;

  (void)drv;

  g_sf32lb52_bt_priv.rxlen = 0;
  g_sf32lb52_bt_priv.drop_rx_until_tx = true;

  ret = sf32lb52_bt_controller_init();
  if (ret < 0)
    {
      return ret;
    }

  ret = sf32lb52_hci_register_callback(sf32lb52_bt_recv_cb);
  if (ret < 0)
    {
